    function _wipeSet(Bytes4Set storage set) internal {
        for (uint256 cursor = set.values.length; cursor > 0; --cursor) {
            bytes4 value = set.values[cursor - 1];
            delete set.indexes[value];
            set.values.pop();
        }
    }
    // end::_wipeSet(Bytes4Set)[]
}
