    // end::_setApprovalForAll(Storage-address-bool)[]

    // tag::_setApprovalForAll(address-bool)[]
    /**
     * @dev Default version of _setApprovalForAll binding to the standard STORAGE_SLOT.
     * @param operator_ The operator.
