        return layoutStruct_.nextTokenId;
    }

    function _nextTokenId() internal view returns (uint256) {
        return _nextTokenId(_layoutStruct());
    }

    function _incrementNextTokenId(Storage storage layoutStruct_) internal returns (uint256 tokenId_) {
        tokenId_ = layoutStruct_.nextTokenId;
        layoutStruct_.nextTokenId = tokenId_ + 1;
    }

    function _incrementNextTokenId() internal returns (uint256) {
        return _incrementNextTokenId(_layoutStruct());
    }

    function _createPosition(
        Storage storage layoutStruct_,
        uint256 tokenId_,
        uint256 originalShares_,
        uint256 effectiveShares_,
        uint256 bonusMultiplier_,
        uint256 unlockTime_
    ) internal {
        layoutStruct_.originalSharesOf[tokenId_] = originalShares_;
        layoutStruct_.effectiveSharesOf[tokenId_] = effectiveShares_;
        layoutStruct_.bonusMultiplierOf[tokenId_] = bonusMultiplier_;
        layoutStruct_.unlockTimeOf[tokenId_] = unlockTime_;
        layoutStruct_.userRewardPerSharePaid[tokenId_] = layoutStruct_.rewardPerShares;
        layoutStruct_.totalShares += effectiveShares_;
        layoutStruct_.totalOriginalShares += originalShares_;
    }

    function _createPosition(
        uint256 tokenId_,
        uint256 originalShares_,
        uint256 effectiveShares_,
        uint256 bonusMultiplier_,
        uint256 unlockTime_
    ) internal {
        _createPosition(_layoutStruct(), tokenId_, originalShares_, effectiveShares_, bonusMultiplier_, unlockTime_);
    }

    function _removePosition(Storage storage layoutStruct_, uint256 tokenId_) internal {
        layoutStruct_.totalShares -= layoutStruct_.effectiveSharesOf[tokenId_];
        layoutStruct_.totalOriginalShares -= layoutStruct_.originalSharesOf[tokenId_];
        delete layoutStruct_.originalSharesOf[tokenId_];
        delete layoutStruct_.effectiveSharesOf[tokenId_];
        delete layoutStruct_.bonusMultiplierOf[tokenId_];
        delete layoutStruct_.unlockTimeOf[tokenId_];
        delete layoutStruct_.userRewardPerSharePaid[tokenId_];
    }

    function _removePosition(uint256 tokenId_) internal {
        _removePosition(_layoutStruct(), tokenId_);
    }

    /**
     * @notice Adds LP to an existing position without affecting lock time.
     * @dev Used when adding to the protocol-owned NFT (sell-in, protocol compound BPT credit).
     *      Reward debt is kept consistent so new principal does not invent phantom pending:
     *      - First shares on a tokenId: set paid = current `rewardPerShares` (baseline).
     *      - Additional shares: preserve previously earned pending by re-basing paid on new effective.
     *      Callers should `_updateGlobalRewards` first (see `addToDETFNFT` / sell path).
     */
    function _addToPosition(Storage storage layoutStruct_, uint256 tokenId_, uint256 additionalShares_) internal {
        if (additionalShares_ == 0) return;

        uint256 oldEff_ = layoutStruct_.effectiveSharesOf[tokenId_];
        if (oldEff_ == 0) {
            // No prior stake: do not inherit historical rewardPerShares as claimable debt.
            layoutStruct_.userRewardPerSharePaid[tokenId_] = layoutStruct_.rewardPerShares;
            layoutStruct_.originalSharesOf[tokenId_] += additionalShares_;
            layoutStruct_.effectiveSharesOf[tokenId_] += additionalShares_;
            layoutStruct_.totalShares += additionalShares_;
            layoutStruct_.totalOriginalShares += additionalShares_;
            return;
        }

        // Preserve pending earned on old stake while increasing principal.
        uint256 pending_ = _earned(layoutStruct_, tokenId_);
        layoutStruct_.originalSharesOf[tokenId_] += additionalShares_;
        layoutStruct_.effectiveSharesOf[tokenId_] += additionalShares_;
        layoutStruct_.totalShares += additionalShares_;
        layoutStruct_.totalOriginalShares += additionalShares_;

        uint256 newEff_ = layoutStruct_.effectiveSharesOf[tokenId_];
        uint256 rps_ = layoutStruct_.rewardPerShares;
        // pending = newEff * (rps - paid) / 1e18  ⇒  paid = rps - pending * 1e18 / newEff
        if (newEff_ > 0 && pending_ > 0) {
            uint256 pendingPerShare_ = (pending_ * 1e18) / newEff_;
            layoutStruct_.userRewardPerSharePaid[tokenId_] =
                rps_ > pendingPerShare_ ? rps_ - pendingPerShare_ : 0;
        } else {
            layoutStruct_.userRewardPerSharePaid[tokenId_] = rps_;
        }
    }

    function _addToPosition(uint256 tokenId_, uint256 additionalShares_) internal {
        _addToPosition(_layoutStruct(), tokenId_, additionalShares_);
    }

    /// @notice L7: add effective-share weight only. Does not change `originalShares`.
    /// @dev Reward debt matches `_addToPosition` first/add paths so new shares do not claim old pot (FC4).
    function _addEffectiveSharesOnly(Storage storage layoutStruct_, uint256 tokenId_, uint256 additionalShares_)
        internal
    {
        if (additionalShares_ == 0) return;

        uint256 oldEff_ = layoutStruct_.effectiveSharesOf[tokenId_];
        if (oldEff_ == 0) {
            layoutStruct_.userRewardPerSharePaid[tokenId_] = layoutStruct_.rewardPerShares;
            layoutStruct_.effectiveSharesOf[tokenId_] += additionalShares_;
            layoutStruct_.totalShares += additionalShares_;
            return;
        }

        uint256 pending_ = _earned(layoutStruct_, tokenId_);
        layoutStruct_.effectiveSharesOf[tokenId_] += additionalShares_;
        layoutStruct_.totalShares += additionalShares_;

        uint256 newEff_ = layoutStruct_.effectiveSharesOf[tokenId_];
        uint256 rps_ = layoutStruct_.rewardPerShares;
        if (newEff_ > 0 && pending_ > 0) {
            uint256 pendingPerShare_ = (pending_ * 1e18) / newEff_;
            layoutStruct_.userRewardPerSharePaid[tokenId_] =
                rps_ > pendingPerShare_ ? rps_ - pendingPerShare_ : 0;
        } else {
            layoutStruct_.userRewardPerSharePaid[tokenId_] = rps_;
        }
    }

    function _addEffectiveSharesOnly(uint256 tokenId_, uint256 additionalShares_) internal {
        _addEffectiveSharesOnly(_layoutStruct(), tokenId_, additionalShares_);
    }

    error BondNotMature(uint256 unlockTime);
    error InsufficientOriginalShares(uint256 needed, uint256 available);

    /**
     * @notice Debits LP 1:1 from original and effective shares (inverse of `_addToPosition`).
     * @dev only protocol NFT. Preserves pending reward debt on remaining effective shares.
     */
    function _removeFromPosition(Storage storage layoutStruct_, uint256 tokenId_, uint256 shares_) internal {
        if (shares_ == 0) return;

        uint256 orig_ = layoutStruct_.originalSharesOf[tokenId_];
        if (shares_ > orig_) {
            revert InsufficientOriginalShares(shares_, orig_);
        }

        uint256 pending_ = _earned(layoutStruct_, tokenId_);
        layoutStruct_.originalSharesOf[tokenId_] -= shares_;
        layoutStruct_.effectiveSharesOf[tokenId_] -= shares_;
        layoutStruct_.totalShares -= shares_;
        layoutStruct_.totalOriginalShares -= shares_;

        uint256 newEff_ = layoutStruct_.effectiveSharesOf[tokenId_];
        uint256 rps_ = layoutStruct_.rewardPerShares;
        if (newEff_ > 0 && pending_ > 0) {
            uint256 pendingPerShare_ = (pending_ * 1e18) / newEff_;
            layoutStruct_.userRewardPerSharePaid[tokenId_] =
                rps_ > pendingPerShare_ ? rps_ - pendingPerShare_ : 0;
        } else {
            layoutStruct_.userRewardPerSharePaid[tokenId_] = rps_;
        }
    }

    function _removeFromPosition(uint256 tokenId_, uint256 shares_) internal {
        _removeFromPosition(_layoutStruct(), tokenId_, shares_);
    }

    /* ---------------------------------------------------------------------- */
    /*                          Share Conversion                              */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice LP inventory used for share↔asset conversion (alignment N10).
     * @dev Numerator is physical `lpToken.balanceOf(this)`. Denominator is `totalOriginalShares`.
     *      Do not use `totalShares` (effective) and do not subtract protocol / id 0 effective shares.
     *      Empty originalShares or empty physical LP is the 1:1 branch in `_convertToShares` /
     *      `_convertToAssets` (no diamond call). Diamond `reserveOfToken` is only for peers that
     *      still custody BPT on the DETF while originalShares are already non-zero.
     */
    function _totalLpReserveForConversion(Storage storage layoutStruct_)
        internal
        view
        returns (uint256 totalLpReserve_, uint256 totalShares_)
    {
        totalShares_ = layoutStruct_.totalOriginalShares;
        totalLpReserve_ = layoutStruct_.lpToken.balanceOf(address(this));
        if (totalLpReserve_ > 0) {
            return (totalLpReserve_, totalShares_);
        }
        if (totalShares_ == 0) {
            return (0, 0);
        }
        // Diamond-custody peers: BPT still on the DETF (not this NFT).
        totalLpReserve_ = IBasicVault(address(layoutStruct_.detf)).reserveOfToken(address(layoutStruct_.lpToken));
    }

    /**
     * @notice Converts LP token amount to shares using proportional math.
     */
    function _convertToShares(Storage storage layoutStruct_, uint256 lpAmount_) internal view returns (uint256 shares_) {
        (uint256 totalLpReserve, uint256 totalShares_) = _totalLpReserveForConversion(layoutStruct_);

        if (totalShares_ == 0 || totalLpReserve == 0) {
            shares_ = lpAmount_;
        } else {
            shares_ = BetterMath._convertToSharesUp(lpAmount_, totalLpReserve, totalShares_, layoutStruct_.decimalOffset);
        }
    }

    function _convertToShares(uint256 lpAmount_) internal view returns (uint256) {
        return _convertToShares(_layoutStruct(), lpAmount_);
    }

    /// @notice Convert inbound LP using a **pre-credit** physical LP snapshot (N10 / donate N4).
    /// @dev After LP has already landed, `convertToShares(ΔL)` would use L' and under-mint id 0.
    function _convertToSharesAtLpReserve(
        Storage storage layoutStruct_,
        uint256 lpAmount_,
        uint256 lpReserveBefore_
    ) internal view returns (uint256 shares_) {
        uint256 totalShares_ = layoutStruct_.totalOriginalShares;
        if (totalShares_ == 0 || lpReserveBefore_ == 0) {
            return lpAmount_;
        }
        shares_ = BetterMath._convertToSharesUp(
            lpAmount_, lpReserveBefore_, totalShares_, layoutStruct_.decimalOffset
        );
    }

    /**
     * @notice Converts shares back to LP token amount.
     */
    function _convertToAssets(Storage storage layoutStruct_, uint256 shares_) internal view returns (uint256 lpAmount_) {
        (uint256 totalLpReserve, uint256 totalShares_) = _totalLpReserveForConversion(layoutStruct_);

        if (totalShares_ == 0 || totalLpReserve == 0) {
            lpAmount_ = shares_;
        } else {
            lpAmount_ = BetterMath._convertToAssets(
                shares_, totalLpReserve, totalShares_, layoutStruct_.decimalOffset, Math.Rounding.Floor
            );
        }
    }

    function _convertToAssets(uint256 shares_) internal view returns (uint256) {
        return _convertToAssets(_layoutStruct(), shares_);
    }

    /* ---------------------------------------------------------------------- */
    /*                          Reward Calculations                           */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Updates the global reward per share based on new reward deposits.
     */
    function _updateGlobalRewards(Storage storage layoutStruct_) internal {
        uint256 totalShares_ = layoutStruct_.totalShares;
        if (totalShares_ == 0) {
            return;
        }

        uint256 currentBalance = layoutStruct_.rewardToken.balanceOf(address(this));
        uint256 lastBalance = layoutStruct_.lastRewardTokenBalance;

        if (currentBalance > lastBalance) {
            uint256 newRewards = currentBalance - lastBalance;
            layoutStruct_.rewardPerShares += (newRewards * 1e18) / totalShares_;
            layoutStruct_.lastRewardTokenBalance = currentBalance;
        }
    }

    function _updateGlobalRewards() internal {
        _updateGlobalRewards(_layoutStruct());
    }

    /**
     * @notice Calculates pending rewards for a token ID.
     */
    function _earned(Storage storage layoutStruct_, uint256 tokenId_) internal view returns (uint256 pending_) {
        uint256 effectiveShares_ = layoutStruct_.effectiveSharesOf[tokenId_];
        if (effectiveShares_ == 0) {
            return 0;
        }

        uint256 rewardPerShare = layoutStruct_.rewardPerShares;

        // Include pending rewards not yet distributed
        uint256 totalShares_ = layoutStruct_.totalShares;
        if (totalShares_ > 0) {
            uint256 currentBalance = layoutStruct_.rewardToken.balanceOf(address(this));
            uint256 lastBalance = layoutStruct_.lastRewardTokenBalance;
            if (currentBalance > lastBalance) {
                uint256 newRewards = currentBalance - lastBalance;
                rewardPerShare += (newRewards * 1e18) / totalShares_;
            }
        }

        uint256 paidPerShare = layoutStruct_.userRewardPerSharePaid[tokenId_];
        if (rewardPerShare <= paidPerShare) {
            return 0;
        }

        pending_ = (effectiveShares_ * (rewardPerShare - paidPerShare)) / 1e18;
    }

    function _earned(uint256 tokenId_) internal view returns (uint256) {
        return _earned(_layoutStruct(), tokenId_);
    }

    /* ---------------------------------------------------------------------- */
    /*                          NFT Metadata                                  */
    /* ---------------------------------------------------------------------- */

    function _generateTokenURI(Storage storage layoutStruct_, uint256 tokenId_) internal view returns (string memory) {
        string memory svg = _buildSVG(layoutStruct_, tokenId_);
        string memory json = _buildJSON(tokenId_, svg);

        return string(abi.encodePacked(METADATA_JSON_PREFIX, Base64.encode(bytes(json))));
    }

    function _generateTokenURI(uint256 tokenId_) internal view returns (string memory) {
        return _generateTokenURI(_layoutStruct(), tokenId_);
    }

    function _buildSVG(Storage storage layoutStruct_, uint256 tokenId_) private view returns (string memory) {
        string memory svg = string.concat(SVG_IMAGE_PREFIX, SVG_IMAGE_TOKEN_ID_PREFIX, tokenId_.toString());

        string memory unlockStr;
        // Handle protocol NFT special case
        if (tokenId_ == layoutStruct_.detfNFTId) {
            unlockStr = "Protocol (No Lock)";
        } else {
            uint256 unlockTime_ = layoutStruct_.unlockTimeOf[tokenId_];
            unlockStr = block.timestamp >= unlockTime_ ? "Unlocked" : _formatDuration(unlockTime_ - block.timestamp);
        }
        svg = string.concat(svg, SVG_UNLOCK_PREFIX, unlockStr);

        uint256 effectiveShares_ = layoutStruct_.effectiveSharesOf[tokenId_];
        svg = string.concat(svg, SVG_SHARES_PREFIX, effectiveShares_.toString());

        uint256 pendingRewards = _earned(layoutStruct_, tokenId_);
        svg = string.concat(svg, SVG_REWARDS_PREFIX, pendingRewards.toString());

        svg = string.concat(svg, SVG_TEXT_CLOSE, SVG_IMAGE_CLOSE);
        // string memory svg = string(abi.encodePacked(
        //     SVG_IMAGE_PREFIX,
        //     SVG_IMAGE_TOKEN_ID_PREFIX,
        //     tokenId_.toString(),
        //     SVG_UNLOCK_PREFIX,
        //     unlockStr,
        //     SVG_SHARES_PREFIX,
        //     effectiveShares_.toString(),
        //     SVG_REWARDS_PREFIX,
        //     pendingRewards.toString(),
        //     SVG_TEXT_CLOSE,
        //     SVG_IMAGE_CLOSE
        // ));

        return svg;
    }

    function _buildJSON(uint256 tokenId_, string memory svg_) private pure returns (string memory) {
        return string(
            abi.encodePacked(
                JSON_NAME_PREFIX,
                tokenId_.toString(),
                JSON_NAME_SUFFIX,
                JSON_DESCRIPTION,
                JSON_IMAGE_PREFIX,
                Base64.encode(bytes(svg_)),
                '"}'
            )
        );
    }

    function _formatDuration(uint256 secs_) private pure returns (string memory) {
        if (secs_ == 0) return "0";
        uint256 d = secs_ / 86400;
        uint256 h = (secs_ % 86400) / 3600;
        uint256 m = (secs_ % 3600) / 60;

        if (d > 0) {
            return string(abi.encodePacked(d.toString(), "d ", h.toString(), "h"));
        }
        if (h > 0) {
            return string(abi.encodePacked(h.toString(), "h ", m.toString(), "m"));
        }
        return string(abi.encodePacked(m.toString(), "m"));
    }
}

// contracts/vaults/detf/common/bondNft/DETFNFTVaultService.sol

/* -------------------------------------------------------------------------- */
/*                                  Indexedex                                 */
/* -------------------------------------------------------------------------- */

/**
 * @title DETFNFTVaultService
 * @author cyotee doge <not_cyotee@proton.me>
 * @notice Stateless service library for Protocol NFT Vault operations.
 * @dev Uses structs to avoid stack-too-deep errors.
 */
library DETFNFTVaultService {
    /* ---------------------------------------------------------------------- */
    /*                              Structs                                   */
    /* ---------------------------------------------------------------------- */

    /// @notice Parameters for harvesting rewards (math inputs only; L-STRUCT-2)
    struct HarvestParams {
        uint256 effectiveShares;
        uint256 rewardPerShares;
        uint256 paidPerShare;
    }

    /// @notice Result of harvest calculation
    struct HarvestResult {
        uint256 rewards;
        bool hasRewards;
    }

    /// @notice Parameters for redemption caller validation (L-STRUCT-2: no unused tokenId)
    struct RedeemParams {
        address recipient;
        address caller;
        address detf;
    }

    /* ---------------------------------------------------------------------- */
    /*                          Harvest Logic                                 */
    /* ---------------------------------------------------------------------- */

    /**
     * @dev Calculates rewards without state modification.
     *      Separates calculation from transfer to reduce stack depth.
     */
    function _calcHarvestRewards(HarvestParams memory params) internal pure returns (HarvestResult memory result) {
        (result.rewards, result.hasRewards) = DETFBondNFTMathLib._calcHarvestRewards(
            params.effectiveShares, params.rewardPerShares, params.paidPerShare
        );
    }

    /**
     * @dev Performs the reward transfer. Call after _calcHarvestRewards.
     */
    function _executeHarvestTransfer(
        DETFNFTVaultRepo.Storage storage layout_,
        uint256 tokenId_,
        address recipient_,
        uint256 rewards_
    ) internal {
        // Update paid amount
        layout_.userRewardPerSharePaid[tokenId_] = layout_.rewardPerShares;
        layout_.lastRewardTokenBalance -= rewards_;

        // Safe transfer - using low-level call to avoid stack issues
        _safeTransfer(layout_.rewardToken, recipient_, rewards_);
    }

    /* ---------------------------------------------------------------------- */
    /*                          Transfer Helpers                              */
    /* ---------------------------------------------------------------------- */

    /**
     * @dev Safe ERC20 transfer without SafeERC20 library to avoid stack depth.
     */
    function _safeTransfer(IERC20 token, address to, uint256 amount) internal {
        DETFSafeTransferLib._safeTransfer(token, to, amount);
    }

    /* ---------------------------------------------------------------------- */
    /*                       Redemption Validation                            */
    /* ---------------------------------------------------------------------- */

    /**
     * @dev Validates redemption caller. Returns true if valid.
     */
    function _validateRedeemCaller(RedeemParams memory params, address owner) internal pure returns (bool) {
        return DETFBondNFTMathLib._validateRedeemCaller(params.caller, params.recipient, params.detf, owner);
    }
}

// contracts/vaults/detf/common/bondNft/DETFNFTVaultCommon.sol

/* -------------------------------------------------------------------------- */
/*                                    Crane                                   */
/* -------------------------------------------------------------------------- */

/* -------------------------------------------------------------------------- */
/*                                  Indexedex                                 */
/* -------------------------------------------------------------------------- */

/**
 * @title DETFNFTVaultCommon
 * @author cyotee doge <not_cyotee@proton.me>
 * @notice Common functionality for Protocol NFT Vault.
 * @dev Contains shared logic for:
 *      - Lock duration validation
 *      - Bonus multiplier calculation
 *      - Position lookup helpers
 */
abstract contract DETFNFTVaultCommon is IDetfErrors {
    using DETFNFTVaultRepo for DETFNFTVaultRepo.Storage;

    /* ---------------------------------------------------------------------- */
    /*                          Error Definitions                             */
    /* ---------------------------------------------------------------------- */

    error BaseSharesZero();
    error DeadlineExceeded(uint256 deadline, uint256 currentTimestamp);
    error LockDurationNotExpired(uint256 currentTime, uint256 unlockTime);
    error BondNotMature(uint256 unlockTime);
    error InsufficientOriginalShares(uint256 needed, uint256 available);
    error NotBondHolder(address owner, address caller);
    error LockDurationTooShort(uint256 duration, uint256 minimum);
    error LockDurationTooLong(uint256 duration, uint256 maximum);
    error DETFNFTCannotBeUnlocked(uint256 tokenId);
    error ReservedBondNftsNotWired();
    error ReservedBondNftIdsUnavailable(uint256 nextTokenId);
    error FeeToZero();
    error ReserveNotLive();
    error InvalidRoute(IERC20 token, IERC20 expected);
    error InvalidPermit2Data();

    /* ---------------------------------------------------------------------- */
    /*                          Bond Terms Helper                             */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Gets bond terms from the fee oracle via StandardVaultRepo.
     * @dev Queries the fee oracle's 3-level fallback chain (vault -> type -> global).
     * @return terms The current bond terms
     */
    function _bondTerms() internal view returns (BondTerms memory terms) {
        terms = DETFBondNFTMathLib._bondTerms(address(this));
    }

    /* ---------------------------------------------------------------------- */
    /*                       Lock Duration Validation                         */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Validates that lock duration is within allowed bounds.
     * @param lockDuration_ Duration to validate
     */
    function _validateLockDuration(DETFNFTVaultRepo.Storage storage, uint256 lockDuration_) internal view {
        BondTerms memory terms = _bondTerms();
        DETFBondNFTMathLib.LockDurationStatus status = DETFBondNFTMathLib._lockDurationStatus(terms, lockDuration_);

        if (status == DETFBondNFTMathLib.LockDurationStatus.TooShort) {
            revert LockDurationTooShort(lockDuration_, terms.minLockDuration);
        }

        if (status == DETFBondNFTMathLib.LockDurationStatus.TooLong) {
            revert LockDurationTooLong(lockDuration_, terms.maxLockDuration);
        }
    }

    /**
     * @notice Calculates bonus multiplier for a given lock duration.
     * @dev Uses quadratic curve: longer locks get exponentially higher bonuses.
     *      bonus = min_bonus + (max_bonus - min_bonus) * (normalized_duration)^2
     *      multiplier = 1 + bonus
     *
     * @param lockDuration_ Lock duration in seconds
     * @return bonusMultiplier_ Multiplier scaled by 1e18 (1e18 = 1x = no bonus)
     */
    function _calcBonusMultiplier(uint256 lockDuration_) internal view returns (uint256 bonusMultiplier_) {
        bonusMultiplier_ = DETFBondNFTMathLib._bonusMultiplierOfVault(address(this), lockDuration_);
    }

    /* ---------------------------------------------------------------------- */
    /*                       Position Lookup Helpers                          */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Gets the position details for a token ID.
     * @param tokenId_ Token ID to query
     * @return position The position data
     */
    function _getPosition(uint256 tokenId_) internal view returns (IDETFNFTVault.Position memory position) {
        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        position = DETFBondNFTMathLib._position(
            layoutStruct.originalSharesOf[tokenId_],
            layoutStruct.effectiveSharesOf[tokenId_],
            layoutStruct.bonusMultiplierOf[tokenId_],
            layoutStruct.unlockTimeOf[tokenId_],
            layoutStruct.userRewardPerSharePaid[tokenId_]
        );
    }

    /**
     * @notice Checks if a token ID is the protocol-owned NFT.
     * @param tokenId_ Token ID to check
     * @return True if this is the protocol NFT
     */
    function _isDETFNFT(uint256 tokenId_) internal view returns (bool) {
        return tokenId_ == DETFNFTVaultRepo._detfNFTId();
    }

    function _isStandingRewardNft(uint256 tokenId_) internal view returns (bool) {
        if (!DETFNFTVaultRepo._reservedIdsWired()) return false;
        return tokenId_ == DETF_FEE_TO_BOND_NFT_ID || tokenId_ == DETF_CREATOR_BOND_NFT_ID;
    }
}

// contracts/vaults/detf/common/bondNft/DETFNFTVaultTarget.sol

/* -------------------------------------------------------------------------- */
/*                                    Crane                                   */
/* -------------------------------------------------------------------------- */

/* -------------------------------------------------------------------------- */
/*                                  Indexedex                                 */
/* -------------------------------------------------------------------------- */

/**
 * @title DETFNFTVaultTarget
 * @author cyotee doge <not_cyotee@proton.me>
 * @notice Implementation of the Protocol NFT Vault.
 * @dev Manages NFT-based bonding positions with time-locked reward-token accrual.
 *      Users lock LP tokens for a duration and receive boosted reward shares.
 *      The DETF diamond owns this vault and is the only entity that can create lock positions.
 */
contract DETFNFTVaultTarget is
    DETFNFTVaultCommon,
    ReentrancyLockModifiers,
    MultiStepOwnableModifiers,
    IDetfNftReserveDonation
{
    // IDETFNFTVault
    using DETFNFTVaultRepo for DETFNFTVaultRepo.Storage;
    using ERC721Repo for ERC721Repo.Storage;
    using BetterSafeERC20 for IERC20;

    /* ---------------------------------------------------------------------- */
    /*                              Events                                    */
    /* ---------------------------------------------------------------------- */

    event NewLock(
        uint256 indexed tokenId, address indexed recipient, uint256 shares, uint256 bonusMultiplier, uint256 unlockTime
    );

    /* ---------------------------------------------------------------------- */
    /*                       Create Position (Owner Only)                     */
    /* ---------------------------------------------------------------------- */

    // /**
    //  * @inheritdoc IDETFNFTVault
    //  * @dev Only the owner (DETF diamond) can call this function.
    //  */
    function createPosition(uint256 shares, uint256 lockDuration, address recipient)
        external
        onlyOwner
        nonReentrant
        returns (uint256 tokenId)
    {
        // Peer path: original = effective base = shares (LP); bonus applied to both.
        tokenId = _createPositionInternal(shares, shares, lockDuration, recipient);
    }

    /// @notice Open bond with LP principal + separate reward-weight base (before lock bonus).
    function createPositionWithEffectiveBase(
        uint256 originalShares,
        uint256 effectiveBase,
        uint256 lockDuration,
        address recipient
    ) external onlyOwner nonReentrant returns (uint256 tokenId) {
        tokenId = _createPositionInternal(originalShares, effectiveBase, lockDuration, recipient);
    }

    function _createPositionInternal(
        uint256 originalShares_,
        uint256 effectiveBase_,
        uint256 lockDuration_,
        address recipient_
    ) private returns (uint256 tokenId) {
        if (originalShares_ == 0) revert BaseSharesZero();
        if (effectiveBase_ == 0) revert BaseSharesZero();

        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        _validateLockDuration(layoutStruct, lockDuration_);

        uint256 bonusMultiplier = _calcBonusMultiplier(lockDuration_);
        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);

        // Reward ledger weight = effectiveBase * lock bonus (PRD open-time mids path).
        uint256 effectiveShares = DETFBondNFTMathLib._calcEffectiveShares(effectiveBase_, bonusMultiplier);

        tokenId = ERC721Repo._mint(recipient_);
        DETFNFTVaultRepo._createPosition(
            layoutStruct,
            tokenId,
            originalShares_,
            effectiveShares,
            bonusMultiplier,
            block.timestamp + lockDuration_
        );

        emit NewLock(tokenId, recipient_, originalShares_, bonusMultiplier, block.timestamp + lockDuration_);
    }

    /// @notice Mints and records the protocol-owned NFT (once).
    function initializeDETFNFT() external onlyOwner nonReentrant returns (uint256 tokenId) {
        tokenId = _initializeProtocolNft();
    }

    /// @notice D7: mint ids 0, 1, 2 (protocol / feeTo / creator) before any user bond.
    function initializeReservedBondNfts(address feeTo, address creator)
        external
        onlyOwner
        nonReentrant
        returns (uint256 protocolId)
    {
        protocolId = _initializeReservedBondNfts(feeTo, creator);
    }

    function reservedBondNftsWired() external view returns (bool) {
        return DETFNFTVaultRepo._reservedIdsWired();
    }

    function _initializeProtocolNft() private returns (uint256 tokenId) {
        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        if (layoutStruct.protocolNftInitialized) {
            return layoutStruct.detfNFTId;
        }
        tokenId = ERC721Repo._mint(address(this));
        DETFNFTVaultRepo._setDETFNFTId(layoutStruct, tokenId);
        DETFNFTVaultRepo._setProtocolNftInitialized(layoutStruct, true);
    }

    function _initializeReservedBondNfts(address feeTo_, address creator_) private returns (uint256 protocolId) {
        if (feeTo_ == address(0)) revert FeeToZero();
        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        if (layoutStruct.reservedIdsWired) {
            return layoutStruct.detfNFTId;
        }

        ERC721Repo.Storage storage erc721_ = ERC721Repo._layoutStruct();
        if (!layoutStruct.protocolNftInitialized) {
            if (erc721_.nextTokenId != DETF_PROTOCOL_BOND_NFT_ID) {
                revert ReservedBondNftIdsUnavailable(erc721_.nextTokenId);
            }
            protocolId = ERC721Repo._mint(address(this));
            DETFNFTVaultRepo._setDETFNFTId(layoutStruct, protocolId);
            DETFNFTVaultRepo._setProtocolNftInitialized(layoutStruct, true);
        } else {
            protocolId = layoutStruct.detfNFTId;
            if (protocolId != DETF_PROTOCOL_BOND_NFT_ID) {
                revert ReservedBondNftIdsUnavailable(protocolId);
            }
        }

        if (ERC721Repo._ownerOf(DETF_FEE_TO_BOND_NFT_ID) == address(0)) {
            if (erc721_.nextTokenId != DETF_FEE_TO_BOND_NFT_ID) {
                revert ReservedBondNftIdsUnavailable(erc721_.nextTokenId);
            }
            ERC721Repo._mint(feeTo_);
        }
        address creatorOwner_ = creator_ == address(0) ? feeTo_ : creator_;
        if (ERC721Repo._ownerOf(DETF_CREATOR_BOND_NFT_ID) == address(0)) {
            if (erc721_.nextTokenId != DETF_CREATOR_BOND_NFT_ID) {
                revert ReservedBondNftIdsUnavailable(erc721_.nextTokenId);
            }
            ERC721Repo._mint(creatorOwner_);
        }
        DETFNFTVaultRepo._setReservedIdsWired(layoutStruct, true);
    }

    /* ---------------------------------------------------------------------- */
    /*                          Redeem Position                               */
    /* ---------------------------------------------------------------------- */

    // /**
    //  * @inheritdoc IDETFNFTVault
    //  */
    function redeemPosition(uint256 tokenId, address recipient, uint256 deadline)
        external
        onlyOwner
        nonReentrant
        returns (uint256 wethOut)
    {
        if (DETFBondNFTMathLib._isDeadlineExceeded(deadline, block.timestamp)) {
            revert DeadlineExceeded(deadline, block.timestamp);
        }

        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();

        // Cannot redeem protocol NFT or standing reward ids 1–2 (D7 / D17).
        if (_isDETFNFT(tokenId) || _isStandingRewardNft(tokenId)) {
            revert DETFNFTRestricted(tokenId);
        }

        // Mature-only: public user close is DETF `closeBondMature`; this path is DETF-only.
        {
            uint256 unlockTime = layoutStruct.unlockTimeOf[tokenId];
            if (block.timestamp < unlockTime) {
                revert BondNotMature(unlockTime);
            }
        }

        // Update and harvest rewards
        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
        uint256 rewards = _harvestRewardsInternal(layoutStruct, tokenId, recipient);

        // N10: 4626 input is originalShares, never effectiveShares (lock bonus is reward weight only).
        uint256 lpAmount = DETFNFTVaultRepo._convertToAssets(layoutStruct, layoutStruct.originalSharesOf[tokenId]);
        DETFNFTVaultRepo._removePosition(layoutStruct, tokenId);

        // Grant approval for burn if DETF is calling
        if (msg.sender == address(layoutStruct.detf)) {
            ERC721Repo._layoutStruct().approvedForTokenId[tokenId] = msg.sender;
        }
        ERC721Repo._burn(tokenId);

        // Canonical Bond NFT → WETH redemption:
        // delegate to the DETF diamond, which custody-holds BPT and executes the pool unwind.
        wethOut = layoutStruct.detf.claimLiquidity(lpAmount, recipient);

        emit IDETFNFTVault.PositionRedeemed(tokenId, recipient, wethOut, rewards);
    }

    /// @notice D25: harvest + remove + burn a mature user bond. Does not credit id 0.
    function retireMaturePosition(uint256 tokenId, address rewardsRecipient)
        external
        onlyOwner
        nonReentrant
        returns (uint256 originalShares, uint256 rewardsClaimed)
    {
        if (_isDETFNFT(tokenId) || _isStandingRewardNft(tokenId)) {
            revert DETFNFTRestricted(tokenId);
        }
        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        address owner_ = ERC721Repo._ownerOf(tokenId);
        if (owner_ == address(0)) revert PositionNotFound(tokenId);
        {
            uint256 unlockTime = layoutStruct.unlockTimeOf[tokenId];
            if (block.timestamp < unlockTime) {
                revert BondNotMature(unlockTime);
            }
        }
        if (rewardsRecipient == address(0)) rewardsRecipient = owner_;
        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
        rewardsClaimed = _harvestRewardsInternal(layoutStruct, tokenId, rewardsRecipient);
        originalShares = layoutStruct.originalSharesOf[tokenId];
        if (originalShares == 0) revert PositionNotFound(tokenId);
        DETFNFTVaultRepo._removePosition(layoutStruct, tokenId);
        ERC721Repo._layoutStruct().approvedForTokenId[tokenId] = msg.sender;
        ERC721Repo._burn(tokenId);
    }

    /* ---------------------------------------------------------------------- */
    /*                          Claim Rewards                                 */
    /* ---------------------------------------------------------------------- */

    // /**
    //  * @inheritdoc IDETFNFTVault
    //  */
    function claimRewards(uint256 tokenId, address recipient) external nonReentrant returns (uint256 rewards) {
        // Bond holder OR package owner (DETF diamond orchestrating holder claim).
        address owner = ERC721Repo._ownerOf(tokenId);
        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        if (!DETFBondNFTMathLib._isCallerOwner(owner, msg.sender) && msg.sender != address(layoutStruct.detf)) {
            revert NotBondHolder(owner, msg.sender);
        }

        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);

        rewards = _harvestRewardsInternal(layoutStruct, tokenId, recipient);

        emit IDETFNFTVault.RewardsClaimed(tokenId, recipient, rewards);
    }

    /**
     * @dev Internal function to harvest rewards for a position.
     *      Uses service library structs to avoid stack-too-deep.
     */
    function _harvestRewardsInternal(DETFNFTVaultRepo.Storage storage layoutStruct_, uint256 tokenId_, address recipient_)
        internal
        returns (uint256 rewards_)
    {
        // Build params struct to reduce stack usage (math fields only)
        DETFNFTVaultService.HarvestParams memory params = DETFNFTVaultService.HarvestParams({
            effectiveShares: layoutStruct_.effectiveSharesOf[tokenId_],
            rewardPerShares: layoutStruct_.rewardPerShares,
            paidPerShare: layoutStruct_.userRewardPerSharePaid[tokenId_]
        });

        //     // Calculate rewards using service
        DETFNFTVaultService.HarvestResult memory result = DETFNFTVaultService._calcHarvestRewards(params);

        if (!result.hasRewards) {
            return 0;
        }

        rewards_ = result.rewards;

        // Execute transfer using service
        DETFNFTVaultService._executeHarvestTransfer(layoutStruct_, tokenId_, recipient_, rewards_);
    }

    /* ---------------------------------------------------------------------- */
    /*                      Protocol NFT Operations                           */
    /* ---------------------------------------------------------------------- */

    /**
     * @dev Only callable by the DETF diamond owner.
     */
    function addToDETFNFT(uint256 tokenId, uint256 shares) external onlyOwner {
        if (tokenId != DETFNFTVaultRepo._detfNFTId()) {
            revert DETFNFTRestricted(tokenId);
        }

        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
        DETFNFTVaultRepo._addToPosition(layoutStruct, tokenId, shares);
    }

    /// @notice L7: effective-share weight only on ids 1 or 2. Does not change `originalShares`.
    function addEffectiveSharesOnly(uint256 tokenId, uint256 shares) external onlyOwner {
        if (!_isStandingRewardNft(tokenId)) {
            revert DETFNFTRestricted(tokenId);
        }
        if (ERC721Repo._ownerOf(tokenId) == address(0)) {
            revert ReservedBondNftsNotWired();
        }
        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
        DETFNFTVaultRepo._addEffectiveSharesOnly(layoutStruct, tokenId, shares);
    }

    /// @notice Debit protocol-NFT principal 1:1 (original and effective). `tokenId` must be `detfNFTId`.
    function removeFromDETFNFT(uint256 tokenId, uint256 shares) external onlyOwner {
        if (tokenId != DETFNFTVaultRepo._detfNFTId()) {
            revert DETFNFTRestricted(tokenId);
        }

        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
        DETFNFTVaultRepo._removeFromPosition(layoutStruct, tokenId, shares);
    }

    /**
     * @notice Sells a user bond NFT into the protocol-owned position.
     */
    function sellPositionToDetfNft(uint256 tokenId, address seller, address rewardsRecipient)
        external
        onlyOwner
        nonReentrant
        returns (uint256 principalShares, uint256 rewardsClaimed)
    {
        DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();

        // Cannot sell protocol NFT or standing reward ids 1–2 (D7 / D17).
        if (_isDETFNFT(tokenId) || _isStandingRewardNft(tokenId)) {
            revert DETFNFTRestricted(tokenId);
        }

        address owner = ERC721Repo._ownerOf(tokenId);
        if (owner != seller) {
            revert NotBondHolder(owner, seller);
        }

        principalShares = layoutStruct.originalSharesOf[tokenId];
        if (principalShares == 0) {
            revert PositionNotFound(tokenId);
        }

        {
            uint256 unlockTime = layoutStruct.unlockTimeOf[tokenId];
            if (block.timestamp < unlockTime) {
                revert BondNotMature(unlockTime);
            }
        }

        if (rewardsRecipient == address(0)) {
            rewardsRecipient = seller;
        }

        // Update + harvest rewards to recipient (per TASK.md).
        DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
        rewardsClaimed = _harvestRewardsInternal(layoutStruct, tokenId, rewardsRecipient);

        // Remove the sold position (burns bonus shares by removing effectiveShares).
        DETFNFTVaultRepo._removePosition(layoutStruct, tokenId);

        // Transfer principal-only shares into the protocol NFT position.
        DETFNFTVaultRepo._addToPosition(layoutStruct, layoutStruct.detfNFTId, principalShares);

        // Burn the sold bond NFT.
        ERC721Repo._layoutStruct().approvedForTokenId[tokenId] = msg.sender;
        ERC721Repo._burn(tokenId);
    }

