    // end::_layoutStruct()[]

    // tag::_initialize(Storage-IPermit2)[]
    /**
     * @dev Argumented version of _initialize to allow direct Storage access.
     * @dev The Storage struct to operate on.
     * @param layoutStruct The Storage struct to operate on.
