        IDiamond.FacetCut[] facetCuts;
        bytes4[] interfaces;
    }
    // end::DiamondConfig[]

    /* -------------------------------------------------------------------------- */
    /*                             Package Metadata                               */
    /* -------------------------------------------------------------------------- */

    // tag::packageName[]
