    bytes32 internal constant STORAGE_SLOT =
        bytes32(uint256(keccak256(abi.encode("crane.access.reentrancy.lock"))) - 1);

    // end::STORAGE_SLOT[]

    // tag::_layoutStruct(bytes32)[]
    /**
