        return _unsafeMul(x.hi, pow2nInv) | (x.lo / pow2n); // `(x.hi << (256 - n)) | (x.lo >> n)`
    }

    function _div256(Uint512_0 memory x, uint256 y) internal pure returns (uint256) {
        if (x.hi == 0) {
            return x.lo / y;
