// contracts/vaults/detf/common/core/DETFBondLifecycleLib.sol

/// @notice Shared bond / detf-NFT lifecycle helpers for true DETFs.
/// @dev Protocol BPT compound is **DETF-orchestrated** (see `DETFProtocolCompoundLib`).
///      Callers that compound detf-owned NFT rewards own the full pipeline after harvest:
///      single-sided DETF join → credit BPT via `_addReservePoolBptToDetfNft`.
///      Preferred pull pattern: harvest only on the successful compound path so join
///      failure leaves pending rewards intact (lazy hooks must not fail the outer user path).
library DETFBondLifecycleLib {
    using BetterSafeERC20 for IERC20;

    error NoSeigniorageToCapture();
    error BondNotMature(uint256 unlockTime);

    /// @notice D2: top up ids 1 and 2 after any event that changes others' effective shares.
    function _topUpFeeCreatorShares(IDetfSelfNftInventoryPolicy vault_, uint256 f_, uint256 c_) internal {
        DETFSeigniorageShareLib._topUpFeeCreatorShares(vault_, f_, c_);
    }

    function _createBondPosition(
        IDetfSelfNftInventoryPolicy vault_,
        uint256 shares_,
        uint256 lockDuration_,
        address recipient_
    ) internal returns (uint256 tokenId_) {
        if (recipient_ == address(0)) {
            recipient_ = msg.sender;
        }

        tokenId_ = vault_.createPosition(shares_, lockDuration_, recipient_);
    }

    /// @notice Open bond with LP principal + rateAsset mid (or other) reward base before lock bonus.
    function _createBondPositionWithEffectiveBase(
        IDetfSelfNftInventoryPolicy vault_,
        uint256 originalShares_,
        uint256 effectiveBase_,
        uint256 lockDuration_,
        address recipient_
    ) internal returns (uint256 tokenId_) {
        if (recipient_ == address(0)) {
            recipient_ = msg.sender;
        }
        tokenId_ = vault_.createPositionWithEffectiveBase(
            originalShares_, effectiveBase_, lockDuration_, recipient_
        );
    }

    function _sellPositionToRebasingClaim(
        IDetfSelfNftInventoryPolicy vault_,
        IRebasingClaimToken rebasingClaimToken_,
        uint256 tokenId_,
        address seller_,
        address recipient_
    ) internal returns (uint256 principalShares_, uint256 rebasingClaimMinted_) {
        uint256 protocolBefore_ = vault_.originalSharesOf(vault_.detfNFTId());
        principalShares_ = _sellPositionToDetfNft(vault_, tokenId_, seller_, recipient_);

        rebasingClaimMinted_ =
            rebasingClaimToken_.mintFromNFTSale(principalShares_, protocolBefore_, recipient_);
    }

    function _sellPositionToDetfNft(
        IDetfSelfNftInventoryPolicy vault_,
        uint256 tokenId_,
        address seller_,
        address recipient_
    ) internal returns (uint256 principalShares_) {
        uint256 unlockTime_ = vault_.unlockTimeOf(tokenId_);
        if (block.timestamp < unlockTime_) {
            revert BondNotMature(unlockTime_);
        }
        (principalShares_,) = vault_.sellPositionToDetfNft(tokenId_, seller_, recipient_);
    }

    /// @notice Harvest free DETF rewards from the detf-owned NFT to this contract.
    /// @dev Free-DETF harvest only — **not** protocol BPT compound. Compound remains
    ///      DETF-orchestrated: after a successful harvest on the compound path, the caller
    ///      must single-sided join DETF into the reserve and credit BPT with
    ///      `_addReservePoolBptToDetfNft`. Prefer not calling this until join will succeed
    ///      (or reverse on join failure) so reward debt never wipes without BPT credit.
    ///      Reverts `NoSeigniorageToCapture` when harvest returns zero.
    function _collectDetfNftRewards(IDetfSelfNftInventoryPolicy vault_) internal returns (uint256 rewardAmount_) {
        rewardAmount_ = vault_.reallocateDetfNftRewards(address(this));
        if (rewardAmount_ == 0) {
            revert NoSeigniorageToCapture();
        }
    }

    /// @notice Credit reserve BPT principal onto the detf-owned NFT after a successful join.
    /// @dev Stage 00 / Phase 1 compound step 6: family join produces `bptAmount_`, then
    ///      this helper approves + `addToDETFNFT`. Do not call if join failed.
    function _addReservePoolBptToDetfNft(
        IERC20 reservePoolToken_,
        IDetfSelfNftInventoryPolicy vault_,
        uint256 detfNftId_,
        uint256 bptAmount_
    ) internal {
        reservePoolToken_.forceApprove(address(vault_), bptAmount_);
        vault_.addToDETFNFT(detfNftId_, bptAmount_);
    }
}

// contracts/vaults/detf/common/core/DETFBondNFTMathLib.sol

library DETFBondNFTMathLib {
    enum LockDurationStatus {
        Valid,
        TooShort,
        TooLong
    }

    function _calcBonusMultiplier(BondTerms memory terms_, uint256 lockDuration_)
        internal
        pure
        returns (uint256 bonusMultiplier_)
    {
        if (terms_.maxLockDuration <= terms_.minLockDuration) {
            return ONE_WAD + terms_.maxBonusPercentage;
        }

        uint256 normalized =
            ((lockDuration_ - terms_.minLockDuration) * ONE_WAD) / (terms_.maxLockDuration - terms_.minLockDuration);
        uint256 curveFactor = (normalized * normalized) / ONE_WAD;

        uint256 bonus;
        if (terms_.maxBonusPercentage >= terms_.minBonusPercentage) {
            bonus = terms_.minBonusPercentage + ((terms_.maxBonusPercentage - terms_.minBonusPercentage) * curveFactor)
                / ONE_WAD;
        } else {
            bonus = terms_.maxBonusPercentage;
        }

        bonusMultiplier_ = ONE_WAD + bonus;
    }

    function _bondTerms(address vault_) internal view returns (BondTerms memory terms_) {
        terms_ = StandardVaultRepo._feeOracle().bondTermsOfVault(vault_);
    }

    function _bonusMultiplierOfVault(address vault_, uint256 lockDuration_)
        internal
        view
        returns (uint256 bonusMultiplier_)
    {
        bonusMultiplier_ = _calcBonusMultiplier(_bondTerms(vault_), lockDuration_);
    }

    function _position(
        uint256 originalShares_,
        uint256 effectiveShares_,
        uint256 bonusMultiplier_,
        uint256 unlockTime_,
        uint256 rewardDebt_
    ) internal pure returns (IDETFNFTVault.Position memory position_) {
        position_ = IDETFNFTVault.Position({
            originalShares: originalShares_,
            effectiveShares: effectiveShares_,
            bonusMultiplier: bonusMultiplier_,
            unlockTime: unlockTime_,
            rewardDebt: rewardDebt_
        });
    }

    function _lockDurationStatus(BondTerms memory terms_, uint256 lockDuration_)
        internal
        pure
        returns (LockDurationStatus status_)
    {
        if (lockDuration_ < terms_.minLockDuration) {
            return LockDurationStatus.TooShort;
        }

        if (lockDuration_ > terms_.maxLockDuration) {
            return LockDurationStatus.TooLong;
        }

        return LockDurationStatus.Valid;
    }

    function _calcHarvestRewards(uint256 effectiveShares_, uint256 rewardPerShares_, uint256 paidPerShare_)
        internal
        pure
        returns (uint256 rewards_, bool hasRewards_)
    {
        if (rewardPerShares_ <= paidPerShare_) {
            return (0, false);
        }

        rewards_ = (effectiveShares_ * (rewardPerShares_ - paidPerShare_)) / ONE_WAD;
        hasRewards_ = rewards_ > 0;
    }

    function _calcEffectiveShares(uint256 shares_, uint256 bonusMultiplier_)
        internal
        pure
        returns (uint256 effectiveShares_)
    {
        effectiveShares_ = (shares_ * bonusMultiplier_) / ONE_WAD;
    }

    function _isDeadlineExceeded(uint256 deadline_, uint256 currentTimestamp_) internal pure returns (bool) {
        return currentTimestamp_ > deadline_;
    }

    function _isUnlockPending(uint256 unlockTime_, uint256 currentTimestamp_) internal pure returns (bool) {
        return currentTimestamp_ < unlockTime_;
    }

    function _isCallerOwner(address owner_, address caller_) internal pure returns (bool) {
        return owner_ == caller_;
    }

    function _validateRedeemCaller(address caller_, address recipient_, address detf_, address owner_)
        internal
        pure
        returns (bool)
    {
        if (owner_ == caller_) {
            return true;
        }

        if (caller_ == detf_ && recipient_ == owner_) {
            return true;
        }

        return false;
    }
}

