        /// @notice Settlement token for zapout quotes (pair / rateAsset as wired by the DETF)
        IERC20 rateAsset;
        /// @notice The protocol-owned NFT token ID
        uint256 detfNFTId;
        /// @notice Owner address (typically the DETF contract)
        address owner;
