// contracts/vaults/detf/protocols/dexes/uniswap/v4/standardExchange/constantProduct/single/interfaces/IUniswapV4SingleStandardExchangeDETF.sol

/// @title IUniswapV4SingleStandardExchangeDETF
/// @notice Info + bonding + claim surface for Uni V4 Single SE CP-buffer true DETF.
interface IUniswapV4SingleStandardExchangeDETF {
    event ThresholdModeSet(ThresholdMode mode, uint256 mintThreshold, uint256 burnThreshold);
    event ProtocolRewardsCompounded(uint256 detfIn, uint256 lpOut);
    event NaturalSupplyExpanded(uint256 mintAmount, uint256 syntheticPrice, uint256 timestamp);
    event ReserveLive(uint256 firstBondTokenId, uint256 lpPrincipal);

    function isReserveLive() external view returns (bool);
    function standardExchangeVault() external view returns (address);
    function standardExchangeVaultShare() external view returns (address);
    function pairToken() external view returns (address);
    function reserveHook() external view returns (address);
    /// @notice Alias of reserveHook for RebasingClaimToken rate calc (`detf.reservePool()`).
    function reservePool() external view returns (address);
    function syntheticPrice() external view returns (uint256);
    function pendingExpansionDetf() external view returns (uint256);
    function mintThreshold() external view returns (uint256);
    function burnThreshold() external view returns (uint256);
    function thresholdMode() external view returns (ThresholdMode);
    function isMintingAllowed() external view returns (bool);
    function isBurningAllowed() external view returns (bool);
    function bondNftVault() external view returns (address);
    function rebasingClaimToken() external view returns (address);
    function feeRecipientNftId() external view returns (uint256);
    function creationPairPerDetfWad() external view returns (uint256);
    /// @notice Pair per DETF on first bond. Resolved storage (0 at init → creation; never 0 if creation was valid).
    function openingPairPerDetfWad() external view returns (uint256);
    function lastExpansionTimestamp() external view returns (uint256);
    function expansionEpochLength() external view returns (uint256);
    function expansionClosureRatePerYearWad() external view returns (uint256);
    function expansionMaxCatchUpEpochs() external view returns (uint256);
    function acceptedBondTokens() external view returns (address[] memory);
    function protocolLp() external view returns (uint256);
    function userBondedLp() external view returns (uint256);

    function compoundProtocolRewards() external returns (uint256 detfIn, uint256 lpOut);

    function bond(
        IERC20 tokenIn,
        uint256 amountIn,
        uint256 lockDuration,
        address recipient,
        bool pretransferred,
        uint256 deadline
    ) external returns (uint256 tokenId, uint256 shares);

    /// @notice Sell bond NFT to protocol; mint rebasing claim to recipient (when claim package wired).
    function sellPositionToDetfNft(uint256 tokenId, address recipient)
        external
        returns (uint256 principalShares);

    function claimRewards(uint256 tokenId, address recipient) external returns (uint256 rewards);

    /// @notice D18: move provided DETF into liquidity; 4626 to id 0; mint claim. No new DETF mint.
    function buyClaim(
        uint256 detfAmount,
        uint256 minClaimOut,
        address recipient,
        bool pretransferred,
        uint256 deadline
    ) external returns (uint256 claimMinted);

    function previewBuyClaim(uint256 detfAmount) external view returns (uint256 claimMinted);

    /// @notice D25 + L2: mature close. `minAmountsOut[0]` is the DETF self-leg and must be 0.
    function closeBondMature(
        uint256 tokenId,
        uint256[] calldata minAmountsOut,
        address recipient,
        uint256 deadline
    ) external returns (uint256[] memory amountsOut);

    function previewCloseBondMature(uint256 tokenId) external view returns (uint256[] memory amountsOut);

    /// @notice D15: redeem rebasing claim → DETF only. Else InvalidRoute.
    function redeemClaim(
        uint256 claimAmount,
        IERC20 tokenOut,
        uint256 minOut,
        address recipient,
        uint256 deadline
    ) external returns (uint256 amountOut);

    function previewRedeemClaim(uint256 claimAmount, IERC20 tokenOut) external view returns (uint256 amountOut);

    /// @notice Bond NFT only. Settle `token` and single-sided join LP to the Bond NFT. No DETF mint. No expansion.
    function joinDonatedCapital(IERC20 token, uint256 amount, uint256 deadline)
        external
        returns (uint256 lpOut);

    function previewJoinDonatedCapital(IERC20 token, uint256 amount)
        external
        view
        returns (uint256 lpOut);

    /// @notice Bond NFT only. D2 top-up after donate credits id 0.
    function notifyReserveDonated() external;

    /// @notice Forwards to Bond NFT donate with `minLpOut = 0`. Pretransfer destination is the NFT. Void ABI freeze.
    function donate(IERC20 token, uint256 amount, bool pretransferred) external;

    /// @notice NFT vault / claim package: unwind protocol LP principal to pair for recipient.
    function claimLiquidity(uint256 lpAmount, address recipient) external returns (uint256 pairOut);

    /// @notice Zapout quote of `lpAmount` reserve LP to pairToken (claim rebase).
    function previewClaimLiquidity(uint256 lpAmount) external view returns (uint256 pairOut);

    event ReserveBondNftWired(
        address indexed reserveHook,
        address bondNftVault,
        uint256 detfNftId,
        uint256 feeRecipientNftId
    );
    event ReserveClaimWired(address indexed reserveHook, address rebasingClaimToken);

    error ReserveNotWired();
    error ReserveHookNotFinalized();
    error ReserveBondNftNotWired();
    error ReserveBondNftAlreadyWired();
    error ReserveClaimAlreadyWired();

    function isReserveHookFinalized() external view returns (bool);
    function isReserveWired() external view returns (bool);
    function completeReserveBondNft() external returns (address bondNftVault);
    function completeReserveClaim() external returns (address rebasingClaimToken);
}

/// @title IUniswapV4SingleStandardExchangeDETDFPkg
/// @notice DFPkg interface — PkgInit / PkgArgs live HERE (Crane rule).
interface IUniswapV4SingleStandardExchangeDETDFPkg is IDiamondFactoryPackage, IStandardVaultPkg {
    error NotCalledByRegistry(address caller);
    error PairTokenNotInSeTokens();
    error DetfInSeTokens();
    error InvalidCreationRate();
    error ZeroAddress();

    struct PkgInit {
        IFacet erc20Facet;
        IFacet erc5267Facet;
        IFacet erc2612Facet;
        IFacet multiAssetBasicVaultFacet;
        IFacet multiAssetStandardVaultFacet;
        IFacet exchangeInFacet;
        IVaultFeeOracleQuery feeOracle;
        IVaultRegistryDeployment vaultRegistryDeployment;
        IPoolManager poolManager;
        IUniswapV4SingleStandardExchangeBufferConstantProductHookPackage hookPkg;
        IDetfSelfNftInventoryDFPkg bondNftVaultPkg;
        IRebasingClaimTokenDFPkg rebasingClaimTokenPkg;
        IDiamondPackageCallBackFactory diamondFactory;
    }

    /// @dev Trailing expansion: zeros resolve via DETFEpochNaturalExpansionLib (epoch 8h, 10%/yr, unlimited catch-up).
    /// @dev thresholdMode: 0 = Policy (default), 1 = Open. Never infer Open from zero thresholds.
    struct PkgArgs {
        string name;
        string symbol;
        IStandardExchangeProxy standardExchangeVault;
        IERC20 standardExchangeVaultShare; // address(0) → vault diamond is share
        IERC20 pairToken;
        uint256 creationPairPerDetfWad; // required non-zero; pair per DETF at 1e18 scale (peg)
        /// @notice Pair per DETF on first bond. 0 → use creation (open at peg).
        uint256 openingPairPerDetfWad;
        uint256 mintThreshold; // 0 → 1.05e18
        uint256 burnThreshold; // 0 → 0.95e18
        ThresholdMode thresholdMode; // 0 = Policy
        uint256 expansionEpochLength; // 0 → 8 hours
        uint256 expansionClosureRatePerYearWad; // 0 → 0.10e18
        uint256 expansionMaxCatchUpEpochs; // 0 = unlimited (kept)
        address creator; // D26; 0 → feeTo owns id 2 (D21)
        /// @notice Rebasing claim ERC-20 name. Empty → DETF name + " Claim".
        string claimName;
        /// @notice Rebasing claim ERC-20 symbol. Empty → DETF symbol + "IR".
        string claimSymbol;
        /// @notice Bond NFT name. Empty → DETF name + " Bond".
        string bondName;
        /// @notice Bond NFT symbol. Empty → DETF symbol + "-BOND".
        string bondSymbol;
    }

    function deployVault(PkgArgs memory args, uint256 mineNonce) external returns (address vault);
}

// contracts/vaults/detf/protocols/dexes/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeDETFCommon.sol

/// @title UniswapV4SingleStandardExchangeDETFCommon
/// @notice Shared pricing, gates, mint split, hook LP helpers, epoch expansion, compound.
abstract contract UniswapV4SingleStandardExchangeDETFCommon is ReentrancyLockModifiers {
    using BetterSafeERC20 for IERC20;

    uint256 internal constant ONE_WAD = 1e18;

    error NotSelf();
    error CompoundJoinProducedZeroLp();
// L-STRUCT-1: MintSplit from detf/common/core/DETFMintSplit.sol

    /* ---------------------------------------------------------------------- */
    /*                              Liveness                                  */
    /* ---------------------------------------------------------------------- */

    function _requireReserveLive() internal view {
        if (!UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().isReserveLive) revert UniswapV4SingleStandardExchangeDETFRepo.ReserveNotLive();
    }

    function _requireReserveWired() internal view {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.bondNftVault) == address(0) || address(s.rebasingClaimToken) == address(0)) {
            revert UniswapV4SingleStandardExchangeDETFRepo.ReserveNotWired();
        }
    }

    /// @dev Deadline + amount only. Disable is inbound-only (`_requireNotDisabled`).
    function _requireActive(uint256 deadline_, uint256 amount_) internal view {
        if (amount_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        if (block.timestamp > deadline_) revert UniswapV4SingleStandardExchangeDETFRepo.DeadlineExpired(deadline_);
    }

    /// @dev First bond cannot credit pre-live unbooked residual (A0).
    function _rejectPretransferredFirstBond(bool pretransferred_, uint256 claimed_) internal pure {
        if (pretransferred_) {
            revert ISecurePullErrors.TransferDeltaInsufficient(claimed_, 0);
        }
    }

    function _requireNotDisabled() internal view {
        address reg = address(StandardVaultRepo._feeOracle());
        if (IVaultRegistryDisableQuery(reg).isDisabled(address(this))) {
            revert IVaultRegistryDisableQuery.VaultDisabled(address(this));
        }
    }

    function _requireBondNft() internal view {
        if (msg.sender != address(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().bondNftVault)) {
            revert UniswapV4SingleStandardExchangeDETFRepo.NotAuthorized(msg.sender);
        }
    }

    function _requireMature(uint256 tokenId_) internal view {
        uint256 unlock_ = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().bondNftVault.unlockTimeOf(tokenId_);
        if (block.timestamp < unlock_) {
            revert UniswapV4SingleStandardExchangeDETFRepo.BondNotMature(unlock_);
        }
    }

    function _requireNotStandingRewardNft(uint256 tokenId_) internal pure {
        if (tokenId_ == DETF_FEE_TO_BOND_NFT_ID || tokenId_ == DETF_CREATOR_BOND_NFT_ID) {
            revert IDetfErrors.DETFNFTRestricted(tokenId_);
        }
    }

    function _protocolOriginalShares() internal view returns (uint256) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        return s.bondNftVault.originalSharesOf(s.bondNftVault.detfNFTId());
    }

    /* ---------------------------------------------------------------------- */
    /*                            Allowlist                                   */
    /* ---------------------------------------------------------------------- */

    function _isAllowlistedTokenIn(IERC20 token_) internal view returns (bool) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(token_) == address(s.standardExchangeVaultShare)) return true;
        if (address(token_) == address(s.pairToken)) return true;
        if (address(token_) == address(this)) return false;

        address[] memory tokens_ = IBasicVault(address(s.standardExchangeVault)).vaultTokens();
        for (uint256 i; i < tokens_.length; ++i) {
            if (tokens_[i] == address(token_)) return true;
        }
        return false;
    }

    /* ---------------------------------------------------------------------- */
    /*                         Bond lock clamp                                */
    /* ---------------------------------------------------------------------- */

    function _effectiveLockDuration(uint256 lockDuration_) internal view returns (uint256 effective_) {
        BondTerms memory terms_ = DETFBondNFTMathLib._bondTerms(address(this));
        if (lockDuration_ < terms_.minLockDuration) {
            revert UniswapV4SingleStandardExchangeDETFRepo.LockDurationTooShort(lockDuration_, terms_.minLockDuration);
        }
        effective_ = lockDuration_ > terms_.maxLockDuration ? terms_.maxLockDuration : lockDuration_;
    }

    function _bonusMultiplier(uint256 effectiveLockDuration_) internal view returns (uint256) {
        return DETFBondNFTMathLib._bonusMultiplierOfVault(address(this), effectiveLockDuration_);
    }

    /* ---------------------------------------------------------------------- */
    /*                         Decimal helpers                                */
    /* ---------------------------------------------------------------------- */

    function _toWad(uint256 amount_, uint8 decimals_) internal pure returns (uint256) {
        if (decimals_ == 18) return amount_;
        if (decimals_ < 18) return amount_ * (10 ** (18 - decimals_));
        return amount_ / (10 ** (decimals_ - 18));
    }

    function _fromWadFloor(uint256 amountWad_, uint8 decimals_) internal pure returns (uint256) {
        if (decimals_ == 18) return amountWad_;
        if (decimals_ < 18) return amountWad_ / (10 ** (18 - decimals_));
        return amountWad_ * (10 ** (decimals_ - 18));
    }

    function _pairDecimals() internal view returns (uint8) {
        return IERC20Metadata(address(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().pairToken)).decimals();
    }

    /* ---------------------------------------------------------------------- */
    /*                    Protocol / bonded LP accounting                     */
    /* ---------------------------------------------------------------------- */

    /// @notice D13: reserve LP is held by the bond NFT vault.
    function _bondLpHolder() internal view returns (address) {
        address bond_ = address(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().bondNftVault);
        return bond_ == address(0) ? address(this) : bond_;
    }

    /// @notice Physical hook LP on the NFT vault (D13).
    function _nftLp() internal view returns (uint256) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        address holder_ = _bondLpHolder();
        return IERC20(s.reserveHook).balanceOf(holder_);
    }

    /// @notice LP on the NFT that is not tracked as user-bonded principal.
    function _protocolLp() internal view returns (uint256) {
        uint256 nftLp_ = _nftLp();
        uint256 user_ = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().userBondedLp;
        return nftLp_ > user_ ? nftLp_ - user_ : 0;
    }

    /// @notice Pull NFT-custodied hook LP onto this diamond before hook withdraw (D13).
    function _pullNftLp(uint256 lpAmount_) internal {
        if (lpAmount_ == 0) return;
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        IERC20 lp_ = IERC20(s.reserveHook);
        uint256 have_ = lp_.balanceOf(address(this));
        if (have_ >= lpAmount_) return;
        uint256 need_ = lpAmount_ - have_;
        address holder_ = _bondLpHolder();
        if (holder_ == address(this)) {
            if (have_ < lpAmount_) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();
            return;
        }
        if (need_ > lp_.balanceOf(holder_)) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();
        IDETFNFTVault(holder_).transferHeldToken(lp_, address(this), need_);
    }

    /// @dev Back-compat name used by burn / claim unwind.
    function _pullProtocolLp(uint256 lpAmount_) internal {
        _pullNftLp(lpAmount_);
    }

    /// @notice Pull LP from bond NFT (maturity close via claimLiquidity).
    function _pullBondLp(uint256 lpAmount_) internal {
        _pullNftLp(lpAmount_);
    }

    function _ensureProtocolLpAvailable(uint256 lpAmount_) internal view {
        if (lpAmount_ > _nftLp()) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();
    }

    /// @dev Pull NFT LP onto the diamond for hook withdraw.
    function _ensureProtocolLpOnDiamond(uint256 lpAmount_) internal {
        _ensureProtocolLpAvailable(lpAmount_);
        _pullNftLp(lpAmount_);
    }

    /// @notice Fully diluted pair value of owned LP (protocol claim + bond NFT + residual diamond).
    function _fdPairWad() internal view returns (uint256 fdPairWad_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        IERC20 lp_ = IERC20(s.reserveHook);
        uint256 totalOwnedLp_ = lp_.balanceOf(address(this));
        address bond_ = address(s.bondNftVault);
        if (bond_ != address(0)) totalOwnedLp_ += lp_.balanceOf(bond_);
        address claim_ = address(s.rebasingClaimToken);
        if (claim_ != address(0)) totalOwnedLp_ += lp_.balanceOf(claim_);
        if (totalOwnedLp_ == 0) return 0;
        uint256 pairOut_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).previewWithdrawSingle(totalOwnedLp_, address(s.pairToken));
        fdPairWad_ = _toWad(pairOut_, _pairDecimals());
    }

    /* ---------------------------------------------------------------------- */
    /*                              Pricing                                   */
    /* ---------------------------------------------------------------------- */

    /// @notice Spot synthetic (excludes pending expansion debt).
    function _syntheticPriceSpot() internal view returns (uint256) {
        uint256 supply_ = ERC20Repo._totalSupply();
        if (supply_ == 0) return ONE_WAD;
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        uint256 fd_ = _fdPairWad();
        if (fd_ == 0) return ONE_WAD;
        // S = (fdPair / supply) / creationRate * 1e18
        // = fdPair * 1e18 / supply * 1e18 / creationPairPerDetfWad
        uint256 mid_ = Math_1.mulDiv(fd_, ONE_WAD, supply_);
        return Math_1.mulDiv(mid_, ONE_WAD, s.creationPairPerDetfWad);
    }

    /// @notice Debt-inclusive synthetic (gates use this).
    function _syntheticPrice() internal view returns (uint256) {
        uint256 supply_ = ERC20Repo._totalSupply();
        if (supply_ == 0) return ONE_WAD;
        uint256 pending_ = _previewPendingExpansionMint();
        uint256 effectiveSupply_ = supply_ + pending_;
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        uint256 fd_ = _fdPairWad();
        if (fd_ == 0) return ONE_WAD;
        uint256 mid_ = Math_1.mulDiv(fd_, ONE_WAD, effectiveSupply_);
        return Math_1.mulDiv(mid_, ONE_WAD, s.creationPairPerDetfWad);
    }

    function _isMintingAllowed() internal view returns (bool) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (!s.isReserveLive) return false;
        return DETFThresholdPolicy._isMintingAllowed(s.thresholdMode, s.mintThreshold, _syntheticPrice());
    }

    function _isBurningAllowed() internal view returns (bool) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (!s.isReserveLive) return false;
        return DETFThresholdPolicy._isBurningAllowed(s.thresholdMode, s.burnThreshold, _syntheticPrice());
    }

    /* ---------------------------------------------------------------------- */
    /*                         Expansion (epoch)                              */
    /* ---------------------------------------------------------------------- */

    function _expansionInput() internal view returns (DETFEpochNaturalExpansionLib.AccrualInput memory in_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        in_.isLive = s.isReserveLive;
        in_.isPolicyMode = s.thresholdMode == ThresholdMode.Policy;
        in_.spotSyntheticPrice = _syntheticPriceSpot();
        in_.totalDetfSupply = ERC20Repo._totalSupply();
        in_.lastExpansionTimestamp = s.lastExpansionTimestamp;
        in_.nowTimestamp = block.timestamp;
        in_.expansionEpochLength = s.expansionEpochLength;
        in_.expansionClosureRatePerYearWad = s.expansionClosureRatePerYearWad;
        in_.expansionMaxCatchUpEpochs = s.expansionMaxCatchUpEpochs;
    }

    function _previewPendingExpansionMint() internal view returns (uint256) {
        return DETFEpochNaturalExpansionLib.previewPendingExpansionMint(_expansionInput());
    }

    /// @dev Realize expansion only on bond / claimRewards / compound. Never on primary mint/burn.
    function _realizeExpansionIfNeeded() internal returns (uint256 mintAmount_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (!s.isReserveLive || s.thresholdMode != ThresholdMode.Policy) return 0;
        if (address(s.bondNftVault) == address(0)) return 0;

        if (s.lastExpansionTimestamp == 0) {
            s.lastExpansionTimestamp = block.timestamp;
            return 0;
        }

        DETFEpochNaturalExpansionLib.AccrualInput memory in_ = _expansionInput();
        uint256 newTs_;
        (mintAmount_, newTs_) = DETFEpochNaturalExpansionLib.computeRealization(in_);
        if (newTs_ != s.lastExpansionTimestamp) {
            s.lastExpansionTimestamp = newTs_;
        }
        if (mintAmount_ > 0) {
            _mintDetf(address(s.bondNftVault), mintAmount_);
            emit IUniswapV4SingleStandardExchangeDETF.NaturalSupplyExpanded(
                mintAmount_, in_.spotSyntheticPrice, newTs_
            );
        }
    }

    /* ---------------------------------------------------------------------- */
    /*                           Mint quote                                   */
    /* ---------------------------------------------------------------------- */

    function _seigniorageIncentiveWad() internal view returns (uint256) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.feeOracle) == address(0)) return 0;
        return s.feeOracle.seigniorageIncentivePercentageOfVault(address(this));
    }

    function _splitMintedDetf(uint256 gross_) internal view returns (MintSplit memory split_) {
        split_.grossDetf = gross_;
        if (gross_ == 0) return split_;
        (uint256 user_, uint256 pot_) = DETFMintSplitLib._splitLiveGross(gross_, _seigniorageIncentiveWad());
        split_.userDetf = user_;
        split_.inventoryDetf = pot_;
        split_.feeToDetf = 0;
    }

    function _splitBondDetf(uint256 joinDetf_) internal view returns (MintSplit memory split_) {
        split_.grossDetf = joinDetf_;
        if (joinDetf_ == 0) return split_;
        (uint256 user_, uint256 pot_,) = DETFMintSplitLib._splitBond(joinDetf_, _seigniorageIncentiveWad());
        split_.userDetf = user_;
        split_.inventoryDetf = pot_;
        split_.feeToDetf = 0;
    }

    /// @notice Unboosted DETF self-leg for a bond join (D24). Empty book uses resolved opening.
    function _quoteBondJoinDetf(uint256 pairAmount_) internal view returns (uint256 detfOut_) {
        if (pairAmount_ == 0) return 0;
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        uint256 opening_ = s.openingPairPerDetfWad;
        uint256 pairWad_ = _toWad(pairAmount_, _pairDecimals());
        if (!s.isReserveLive || !_hookIsLive()) {
            detfOut_ = Math_1.mulDiv(pairWad_, ONE_WAD, opening_);
            return detfOut_ == 0 ? pairAmount_ : detfOut_;
        }
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook);
        uint256 rawReserve_ = hook_.rawReserve();
        uint256 pairReserve_ = hook_.currency0() == address(s.pairToken)
            ? hook_.reserveCurrency0()
            : hook_.reserveCurrency1();
        if (rawReserve_ == 0 || pairReserve_ == 0) {
            detfOut_ = Math_1.mulDiv(pairWad_, ONE_WAD, opening_);
            return detfOut_ == 0 ? pairAmount_ : detfOut_;
        }
        detfOut_ = pairAmount_ * rawReserve_ / pairReserve_;
        if (detfOut_ == 0) {
            detfOut_ = Math_1.mulDiv(pairWad_, ONE_WAD, s.creationPairPerDetfWad);
        }
    }

    function _topUpFeeCreatorShares() internal {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.bondNftVault) == address(0)) return;
        (, uint256 f_, uint256 c_) = s.feeOracle.seigniorageSplitOfVault(address(this));
        DETFBondLifecycleLib._topUpFeeCreatorShares(
            IDetfSelfNftInventoryPolicy(address(s.bondNftVault)), f_, c_
        );
    }

    /// @notice Closed-form DETF out for exact-in pair notional against live hook effective reserves.
    /// @dev Pre-live / empty: uses creation rate. Live: ConstProd sale of pair → raw DETF face.
    function _quoteDetfAgainstReserve(uint256 pairAmount_) internal view returns (uint256 detfOut_) {
        if (pairAmount_ == 0) return 0;
        uint256 creation_ = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().creationPairPerDetfWad;
        uint256 pairWad_ = _toWad(pairAmount_, _pairDecimals());
        if (!UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().isReserveLive || !_hookIsLive()) {
            detfOut_ = Math_1.mulDiv(pairWad_, ONE_WAD, creation_);
            return detfOut_ == 0 ? pairAmount_ : detfOut_;
        }
        detfOut_ = _quoteDetfLive(pairAmount_, pairWad_, creation_);
    }

    function _quoteDetfLive(uint256 pairAmount_, uint256 pairWad_, uint256 creation_)
        private
        view
        returns (uint256 detfOut_)
    {
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().reserveHook);
        uint256 rawReserve_ = hook_.rawReserve();
        uint256 pairReserve_ = hook_.currency0() == address(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().pairToken)
            ? hook_.reserveCurrency0()
            : hook_.reserveCurrency1();
        if (rawReserve_ == 0 || pairReserve_ == 0) {
            detfOut_ = Math_1.mulDiv(pairWad_, ONE_WAD, creation_);
            return detfOut_ == 0 ? pairAmount_ : detfOut_;
        }
        detfOut_ = ConstProdUtils._saleQuote(pairAmount_, pairReserve_, rawReserve_, 300, 100_000);
        if (detfOut_ == 0) {
            detfOut_ = Math_1.mulDiv(pairWad_, ONE_WAD, creation_);
        }
    }

    function _hookIsLive() internal view returns (bool) {
        try IUniswapV4SingleStandardExchangeBufferConstantProductHook(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().reserveHook).isLive() returns (bool live_) {
            return live_;
        } catch {
            return false;
        }
    }

    /* ---------------------------------------------------------------------- */
    /*                         Hook deposit / withdraw                        */
    /* ---------------------------------------------------------------------- */

    function _depositSinglePair(uint256 pairAmount_, address lpTo_) internal returns (uint256 lpOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        s.pairToken.forceApprove(s.reserveHook, pairAmount_);
        lpOut_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).depositSingle(
            address(s.pairToken), pairAmount_, lpTo_, 0, block.timestamp + 1
        );
    }

    function _depositProportional(uint256 detfAmount_, uint256 pairAmount_, address lpTo_)
        internal
        returns (uint256 lpOut_)
    {
        address hookAddr_ = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().reserveHook;
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(hookAddr_);
        bool detfIs0_ = hook_.currency0() == address(this);
        uint256 a0_ = detfIs0_ ? detfAmount_ : pairAmount_;
        uint256 a1_ = detfIs0_ ? pairAmount_ : detfAmount_;
        if (detfAmount_ > 0) IERC20(address(this)).forceApprove(hookAddr_, detfAmount_);
        if (pairAmount_ > 0) UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().pairToken.forceApprove(hookAddr_, pairAmount_);
        (lpOut_,,) = hook_.deposit(a0_, a1_, lpTo_, 0, block.timestamp + 1);
    }

    function _depositSingleDetf(uint256 detfAmount_, address lpTo_) internal returns (uint256 lpOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        IERC20(address(this)).forceApprove(s.reserveHook, detfAmount_);
        lpOut_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).depositSingle(address(this), detfAmount_, lpTo_, 0, block.timestamp + 1);
    }

    /// @dev Cap zap-in so MIN-book D25-7 rejoin still mints lpOut > 0 (full amount would NotLive).
    function _depositSingleDetfCapped(uint256 detfAmount_, address lpTo_)
        internal
        returns (uint256 lpOut_)
    {
        if (detfAmount_ == 0) return 0;
        uint256 raw_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().reserveHook).rawReserve();
        uint256 cap_ = raw_ / 4;
        if (cap_ == 0) cap_ = detfAmount_ < 1e3 ? detfAmount_ : 1e3;
        uint256 joinAmt_ = detfAmount_ < cap_ ? detfAmount_ : cap_;
        if (joinAmt_ == 0) return 0;
        lpOut_ = _depositSingleDetf(joinAmt_, lpTo_);
    }

    /// @dev Repeat capped DETF joins so last-exit leftover becomes id 0 LP. Do not
    ///      send leftover DETF to the Bond NFT (that books as rewards and extracts to ids 1–2).
    function _depositSingleDetfUntilDust(uint256 detfAmount_, address lpTo_)
        internal
        returns (uint256 lpOut_)
    {
        if (detfAmount_ == 0) return 0;
        IERC20 detfToken_ = IERC20(address(this));
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook);
        for (uint256 i; i < 64; ++i) {
            uint256 remaining_ = detfToken_.balanceOf(address(this));
            if (remaining_ == 0) break;
            uint256 cap_ = hook_.rawReserve() / 4;
            if (cap_ == 0) cap_ = remaining_ < 1e3 ? remaining_ : 1e3;
            uint256 joinAmt_ = remaining_ < cap_ ? remaining_ : cap_;
            if (joinAmt_ == 0) break;
            detfToken_.forceApprove(s.reserveHook, joinAmt_);
            try hook_.depositSingle(address(this), joinAmt_, lpTo_, 0, block.timestamp + 1) returns (uint256 minted_) {
                if (minted_ == 0) break;
                lpOut_ += minted_;
            } catch {
                detfToken_.forceApprove(s.reserveHook, 0);
                break;
            }
        }
    }

    function _withdrawSinglePair(uint256 lpAmount_, address to_) internal returns (uint256 pairOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        IERC20(s.reserveHook).forceApprove(s.reserveHook, lpAmount_);
        pairOut_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).withdrawSingle(
            lpAmount_, address(s.pairToken), to_, 0, block.timestamp + 1
        );
    }

    function _withdrawProportional(uint256 lpAmount_)
        internal
        returns (uint256 detfOut_, uint256 pairOut_)
    {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook);
        IERC20(s.reserveHook).forceApprove(s.reserveHook, lpAmount_);
        (uint256 a0_, uint256 a1_) = hook_.withdraw(lpAmount_, address(this), 0, 0, block.timestamp + 1);
        bool detfIs0_ = hook_.currency0() == address(this);
        detfOut_ = detfIs0_ ? a0_ : a1_;
        pairOut_ = detfIs0_ ? a1_ : a0_;
    }

    function _previewProportional(uint256 lpAmount_)
        internal
        view
        returns (uint256 detfOut_, uint256 pairOut_)
    {
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().reserveHook);
        (uint256 a0_, uint256 a1_) = hook_.previewWithdraw(lpAmount_);
        bool detfIs0_ = hook_.currency0() == address(this);
        detfOut_ = detfIs0_ ? a0_ : a1_;
        pairOut_ = detfIs0_ ? a1_ : a0_;
    }

    function _previewProportionalDetf(uint256 lpAmount_) internal view returns (uint256) {
        (uint256 detfOut_,) = _previewProportional(lpAmount_);
        return detfOut_;
    }

    /// @dev D15 zap-out: proportional DETF plus pair→DETF at the public swap fee.
    function _previewZapOutToDetf(uint256 lpAmount_) internal view returns (uint256 detfOut_) {
        (uint256 detf_, uint256 pair_) = _previewProportional(lpAmount_);
        detfOut_ = detf_;
        if (pair_ == 0) return detfOut_;
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().reserveHook);
        bool zfo_ = hook_.currency0() == address(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().pairToken);
        detfOut_ += hook_.previewSwapExactIn(zfo_, pair_);
    }

    /* ---------------------------------------------------------------------- */
    /*                     Protocol seigniorage compound                      */
    /* ---------------------------------------------------------------------- */

    function _tryCompoundProtocolRewards() internal returns (uint256 detfIn_, uint256 lpOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.bondNftVault) == address(0) || !s.isReserveLive) {
            return (0, 0);
        }

        // Realize expansion first (public compound IS a realize path).
        _realizeExpansionIfNeeded();

        uint256 protocolId_ = s.bondNftVault.detfNFTId();
        uint256 pending_ = s.bondNftVault.pendingRewards(protocolId_);
        if (!DETFProtocolCompoundLib.isCompoundable(pending_)) {
            return (0, 0);
        }

        try this.compoundProtocolRewardsAtomic() returns (uint256 d_, uint256 l_) {
            detfIn_ = d_;
            lpOut_ = l_;
            if (lpOut_ > 0) {
                emit IUniswapV4SingleStandardExchangeDETF.ProtocolRewardsCompounded(detfIn_, lpOut_);
            }
        } catch {
            return (0, 0);
        }
    }

    function compoundProtocolRewardsAtomic() external returns (uint256 detfIn_, uint256 lpOut_) {
        if (msg.sender != address(this)) revert NotSelf();
        return _compoundProtocolRewardsAtomic();
    }

    function _compoundProtocolRewardsAtomic() internal returns (uint256 detfIn_, uint256 lpOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        IDETFNFTVault vault_ = s.bondNftVault;

        detfIn_ = vault_.reallocateDetfNftRewards(address(this));
        if (detfIn_ == 0) return (0, 0);

        // D13: join LP onto the NFT vault; credit id 0 originalShares.
        lpOut_ = _depositSingleDetf(detfIn_, _bondLpHolder());
        if (lpOut_ == 0) revert CompoundJoinProducedZeroLp();

        DETFBondLifecycleLib._addReservePoolBptToDetfNft(
            IERC20(s.reserveHook),
            IDetfSelfNftInventoryPolicy(address(vault_)),
            s.detfNftId == 0 ? vault_.detfNFTId() : s.detfNftId,
            lpOut_
        );
        _topUpFeeCreatorShares();
    }

    /// @notice NFT vault / claim-authorized unwind of LP → pair.
    /// @dev Bond NFT maturity pulls user LP from NFT; claim/self pulls protocol LP from rebasing.
    function _claimLiquidity(uint256 lpAmount_, address recipient_) internal returns (uint256 pairOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        address bond_ = address(s.bondNftVault);
        address claim_ = address(s.rebasingClaimToken);
        if (msg.sender != bond_ && msg.sender != claim_ && msg.sender != address(this)) {
            revert UniswapV4SingleStandardExchangeDETFRepo.NotAuthorized(msg.sender);
        }
        if (lpAmount_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        if (msg.sender == bond_) {
            _pullBondLp(lpAmount_);
        } else {
            _ensureProtocolLpOnDiamond(lpAmount_);
        }
        pairOut_ = _withdrawSinglePair(lpAmount_, recipient_ == address(0) ? msg.sender : recipient_);
        // Money route end-order: pair leave diamond → full hold-set sync (L-DETF-END-ORDER).
        _syncAllExpectedHoldReserves();
    }

    /* ---------------------------------------------------------------------- */
    /*                              Transfers                                 */
    /* ---------------------------------------------------------------------- */

    /// @dev Reserve-delta pull (L-DETF-LOCAL-PUSH). `pretransferred=true`: credit claimed only when
    ///      claimed <= U = B - R. `false`: pull delta only (FoT-safe; does not add prior U).
    function _pullToken(IERC20 token_, uint256 amount_, bool pretransferred_) internal returns (uint256 actual_) {
        uint256 R = MultiAssetBasicVaultRepo._reserveOfToken(address(token_));
        uint256 B0 = token_.balanceOf(address(this));
        if (!pretransferred_) {
            token_.safeTransferFrom(msg.sender, address(this), amount_);
            return token_.balanceOf(address(this)) - B0;
        }
        uint256 U = B0 - R;
        if (amount_ > U) {
            revert ISecurePullErrors.TransferDeltaInsufficient(amount_, U);
        }
        return amount_;
    }

    /// @dev Full expected-hold sync after outer refund (L-DETF-END-ORDER).
    function _syncAllExpectedHoldReserves() internal {
        address[] memory tokens = MultiAssetBasicVaultRepo._vaultTokens();
        for (uint256 i; i < tokens.length; ++i) {
            IERC20 t = IERC20(tokens[i]);
            MultiAssetBasicVaultRepo._updateReserve(t, t.balanceOf(address(this)));
        }
    }

    /// @dev Nested exchangeIn fund: push + true; amountIn_==0 skips entire call (L-DETF-ZERO-NESTED).
    function _nestedExchangeInPush(
        IStandardExchangeIn host_,
        IERC20 tokenIn_,
        uint256 amountIn_,
        IERC20 tokenOut_,
        uint256 minOut_,
        address recipient_,
        uint256 deadline_
    ) internal returns (uint256 amountOut_) {
        if (amountIn_ == 0) return 0;
        tokenIn_.safeTransfer(address(host_), amountIn_);
        amountOut_ = host_.exchangeIn(
            tokenIn_, amountIn_, tokenOut_, minOut_, recipient_, true, deadline_
        );
    }

    function _feeTo() internal view returns (address) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        return address(s.feeOracle.feeTo());
    }

    function _mintDetf(address to_, uint256 amount_) internal {
        if (amount_ > 0) ERC20Repo._mint(to_, amount_);
    }

    function _burnDetf(address from_, uint256 amount_) internal {
        ERC20Repo._burn(from_, amount_);
    }

    /// @notice Host LP preview for donate join. Unknown / inert returns 0. `lpToken` is not joinable.
    function _previewJoinDonatedCapital(IERC20 token_, uint256 amount_)
        internal
        view
        returns (uint256 lpOut_)
    {
        if (amount_ == 0) return 0;
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (!s.isReserveLive) return 0;
        address hookAddr_ = s.reserveHook;
        if (address(token_) == hookAddr_) return 0;
        IUniswapV4SingleStandardExchangeBufferConstantProductHook hook_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(hookAddr_);
        if (address(token_) == address(this)) {
            return hook_.previewDepositSingle(address(this), amount_);
        }
        if (address(token_) == address(s.pairToken)) {
            return hook_.previewDepositSingle(address(s.pairToken), amount_);
        }
        if (_isAllowlistedTokenIn(token_)) {
            try s.standardExchangeVault.previewExchangeIn(token_, amount_, s.pairToken) returns (uint256 pairOut_) {
                if (pairOut_ == 0) return 0;
                return hook_.previewDepositSingle(address(s.pairToken), pairOut_);
            } catch {
                return 0;
            }
        }
        return 0;
    }

    /// @dev Settle tokenIn to pair amount (pair itself, SE share→pair, or SE token→pair).
    function _settleToPair(IERC20 tokenIn_, uint256 amountIn_, bool pretransferred_, uint256 deadline_)
        internal
        returns (uint256 pairAmount_)
    {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(tokenIn_) == address(s.pairToken)) {
            return _pullToken(tokenIn_, amountIn_, pretransferred_);
        }
        uint256 pulled_ = _pullToken(tokenIn_, amountIn_, pretransferred_);
        if (address(tokenIn_) == address(s.standardExchangeVaultShare) || _isAllowlistedTokenIn(tokenIn_)) {
            // Nested SE fund: push + pretransferred=true (L-DETF-PUSH-NESTED).
            pairAmount_ = _nestedExchangeInPush(
                IStandardExchangeIn(address(s.standardExchangeVault)),
                tokenIn_, pulled_, s.pairToken, 0, address(this), deadline_
            );
            return pairAmount_;
        }
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(tokenIn_, s.pairToken);
    }
}

// contracts/vaults/detf/protocols/dexes/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeDETFExchangeOutTarget.sol

/// @title UniswapV4SingleStandardExchangeDETFExchangeOutTarget
/// @notice Primary burn: free DETF → pair. D12 burns DETF. D13 sizes `lpOut = detfIn * nftLp / supply`.
/// @dev D14 / L4: no usage-fee peel and no amountIn bonus on burn. Does NOT realize expansion.
abstract contract UniswapV4SingleStandardExchangeDETFExchangeOutTarget is
    UniswapV4SingleStandardExchangeDETFCommon
{
    using BetterSafeERC20 for IERC20;

    function _burnDetfExactIn(
        uint256 detfIn_,
        IERC20 tokenOut_,
        uint256 minOut_,
        address recipient_,
        bool pretransferred_,
        uint256 /* deadline_ */
    ) internal returns (uint256 amountOut_) {
        _requireReserveLive();
        _realizeExpansionIfNeeded();
        if (!_isBurningAllowed()) {
            UniswapV4SingleStandardExchangeDETFRepo.Storage storage s0 = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
            revert UniswapV4SingleStandardExchangeDETFRepo.BurningNotAllowed(_syntheticPrice(), s0.burnThreshold);
        }
        if (recipient_ == address(0)) recipient_ = msg.sender;

        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(tokenOut_) != address(s.pairToken)) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(this)), tokenOut_);
        }

        uint256 actualIn_ = _pullToken(IERC20(address(this)), detfIn_, pretransferred_);
        uint256 supply_ = ERC20Repo._totalSupply();
        uint256 nftLp_ = _nftLp();
        if (nftLp_ == 0 || supply_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();

        uint256 lpOut_ = actualIn_ * nftLp_ / supply_;
        if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();

        _burnDetf(address(this), actualIn_);
        _ensureProtocolLpOnDiamond(lpOut_);
        amountOut_ = _withdrawSinglePair(lpOut_, recipient_);

        if (amountOut_ < minOut_) {
            revert IStandardExchangeErrors.MinAmountNotMet(minOut_, amountOut_);
        }
        _syncAllExpectedHoldReserves();
    }

    function _previewBurnDetfExactIn(uint256 detfIn_, IERC20 tokenOut_)
        internal
        view
        returns (uint256 amountOut_)
    {
        if (!UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().isReserveLive) return 0;
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(tokenOut_) != address(s.pairToken)) return 0;
        if (detfIn_ == 0) return 0;
        uint256 supply_ = ERC20Repo._totalSupply();
        uint256 nftLp_ = _nftLp();
        if (nftLp_ == 0 || supply_ == 0) return 0;
        uint256 lpOut_ = detfIn_ * nftLp_ / supply_;
        if (lpOut_ == 0) return 0;
        amountOut_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).previewWithdrawSingle(lpOut_, address(s.pairToken));
    }
}

// contracts/vaults/detf/protocols/dexes/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeDETFExchangeInTarget.sol

/// @title UniswapV4SingleStandardExchangeDETFExchangeInTarget
/// @notice Exact-in mint (pair/share/SE token), burn when tokenIn is DETF, SE passthrough.
/// @dev Primary mint does NOT realize expansion or advance lastExpansionTimestamp.
abstract contract UniswapV4SingleStandardExchangeDETFExchangeInTarget is
    UniswapV4SingleStandardExchangeDETFExchangeOutTarget
{
    using BetterSafeERC20 for IERC20;

    function exchangeIn(
        IERC20 tokenIn_,
        uint256 amountIn_,
        IERC20 tokenOut_,
        uint256 minAmountOut_,
        address recipient_,
        bool pretransferred_,
        uint256 deadline_
    ) public virtual nonReentrant returns (uint256 amountOut_) {
        _requireActive(deadline_, amountIn_);
        if (address(tokenIn_) != address(this)) {
            _requireNotDisabled();
        }
        if (recipient_ == address(0)) recipient_ = msg.sender;

        if (address(tokenIn_) == address(this)) {
            return _burnDetfExactIn(amountIn_, tokenOut_, minAmountOut_, recipient_, pretransferred_, deadline_);
        }
        if (address(tokenOut_) == address(this)) {
            amountOut_ = _mintPath(tokenIn_, amountIn_, recipient_, pretransferred_, deadline_);
            if (amountOut_ < minAmountOut_) {
                revert IStandardExchangeErrors.MinAmountNotMet(minAmountOut_, amountOut_);
            }
            _syncAllExpectedHoldReserves();
            return amountOut_;
        }
        if (address(tokenIn_) != address(this)) {
            amountOut_ =
                _sePassthrough(tokenIn_, amountIn_, tokenOut_, minAmountOut_, recipient_, pretransferred_, deadline_);
            _syncAllExpectedHoldReserves();
            return amountOut_;
        }
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(tokenIn_, tokenOut_);
    }

    function _mintPath(
        IERC20 tokenIn_,
        uint256 amountIn_,
        address recipient_,
        bool pretransferred_,
        uint256 deadline_
    ) private returns (uint256 userOut_) {
        _requireReserveLive();
        _realizeExpansionIfNeeded();
        if (!_isMintingAllowed()) {
            revert UniswapV4SingleStandardExchangeDETFRepo.MintingNotAllowed(_syntheticPrice(), UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().mintThreshold);
        }
        userOut_ = _mintDetfFromPair(_settleToPair(tokenIn_, amountIn_, pretransferred_, deadline_), recipient_);
    }

    function _sePassthrough(
        IERC20 tokenIn_,
        uint256 amountIn_,
        IERC20 tokenOut_,
        uint256 minAmountOut_,
        address recipient_,
        bool pretransferred_,
        uint256 deadline_
    ) private returns (uint256 amountOut_) {
        if (!_isAllowlistedTokenIn(tokenIn_) || !_isAllowlistedTokenIn(tokenOut_)) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(tokenIn_, tokenOut_);
        }
        uint256 pulled_ = _pullToken(tokenIn_, amountIn_, pretransferred_);
        address se_ = address(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().standardExchangeVault);
        // Nested SE fund: push + pretransferred=true (L-DETF-PUSH-NESTED).
        amountOut_ = _nestedExchangeInPush(
            IStandardExchangeIn(se_),
            tokenIn_,
            pulled_,
            tokenOut_,
            minAmountOut_,
            recipient_,
            deadline_
        );
    }

    /// @dev Live mint: D8 bonus on amountIn, D27/D3 split. No DETF into reserve (D11). No feeTo mint (D14).
    ///      Pair LP sits on the NFT without new originalShares (NAV change). Does NOT realize expansion.
    function _mintDetfFromPair(uint256 pairAmount_, address recipient_) internal returns (uint256 userOut_) {
        uint256 pairBoosted_ = Math_1.mulDiv(pairAmount_, ONE_WAD + _seigniorageIncentiveWad(), ONE_WAD);
        MintSplit memory split_ = _splitMintedDetf(_quoteDetfAgainstReserve(pairBoosted_));
        _depositSinglePair(pairAmount_, _bondLpHolder());
        _mintDetf(recipient_, split_.userDetf);
        address bondVault_ = address(UniswapV4SingleStandardExchangeDETFRepo._layoutStruct().bondNftVault);
        if (split_.inventoryDetf > 0 && bondVault_ != address(0)) {
            _mintDetf(bondVault_, split_.inventoryDetf);
        }
        return split_.userDetf;
    }

    function previewExchangeIn(IERC20 tokenIn_, uint256 amountIn_, IERC20 tokenOut_)
        public
        view
        virtual
        returns (uint256 amountOut_)
    {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();

        // Claim-token rate path: reserve hook LP → pair (rateAsset).
        if (address(tokenIn_) == s.reserveHook && address(tokenOut_) == address(s.pairToken)) {
            return IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).previewWithdrawSingle(amountIn_, address(s.pairToken));
        }

        if (address(tokenIn_) == address(this)) {
            return _previewBurnDetfExactIn(amountIn_, tokenOut_);
        }
        if (address(tokenOut_) == address(this)) {
            if (!s.isReserveLive) return 0;
            // Approximate pair settlement for preview when tokenIn is pair.
            uint256 pairAmount_ = amountIn_;
            if (address(tokenIn_) != address(s.pairToken)) {
                // Best-effort SE preview
                try s.standardExchangeVault.previewExchangeIn(tokenIn_, amountIn_, s.pairToken) returns (
                    uint256 p_
                ) {
                    pairAmount_ = p_;
                } catch {
                    return 0;
                }
            }
            uint256 incentive_ = _seigniorageIncentiveWad();
            uint256 pairBoosted_ = Math_1.mulDiv(pairAmount_, ONE_WAD + incentive_, ONE_WAD);
            uint256 gross_ = _quoteDetfAgainstReserve(pairBoosted_);
            MintSplit memory split_ = _splitMintedDetf(gross_);
            return split_.userDetf;
        }
        if (_isAllowlistedTokenIn(tokenIn_) && _isAllowlistedTokenIn(tokenOut_)) {
            try s.standardExchangeVault.previewExchangeIn(tokenIn_, amountIn_, tokenOut_) returns (uint256 o_) {
                return o_;
            } catch {
                return 0;
            }
        }
        return 0;
    }
}

// contracts/vaults/detf/protocols/dexes/uniswap/v4/standardExchange/constantProduct/single/UniswapV4SingleStandardExchangeDETFBondingTarget.sol

/// @title UniswapV4SingleStandardExchangeDETFBondingTarget
/// @notice Bond with pair/share/SE token. First bond bootstraps at opening (permissionless).
/// @dev Live bonds: no synthetic gate; realize expansion then reward update.
abstract contract UniswapV4SingleStandardExchangeDETFBondingTarget is
    UniswapV4SingleStandardExchangeDETFCommon,
    IUniswapV4SingleStandardExchangeDETF
{
    using BetterSafeERC20 for IERC20;

    function bond(
        IERC20 tokenIn_,
        uint256 amountIn_,
        uint256 lockDuration_,
        address recipient_,
        bool pretransferred_,
        uint256 deadline_
    ) public virtual nonReentrant returns (uint256 tokenId_, uint256 shares_) {
        _requireNotDisabled();
        _requireActive(deadline_, amountIn_);
        if (recipient_ == address(0)) recipient_ = msg.sender;

        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (s.isReserveLive) {
            _realizeExpansionIfNeeded();
        } else {
            _rejectPretransferredFirstBond(pretransferred_, amountIn_);
            _requireReserveWired();
        }

        uint256 pairAmount_ = _settleToPair(tokenIn_, amountIn_, pretransferred_, deadline_);
        // D24 unboosted join `G`. Empty book uses openingPairPerDetfWad. L1 free U=G then D3+D4 pot.
        uint256 detfForPool_ = _quoteBondJoinDetf(pairAmount_);
        if (detfForPool_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.FirstBondBelowMinimumLiquidity();
        MintSplit memory split_ = _splitBondDetf(detfForPool_);

        _mintDetf(address(this), detfForPool_);
        shares_ = _depositProportional(detfForPool_, pairAmount_, _bondLpHolder());
        if (!s.isReserveLive) {
            if (shares_ == 0 || shares_ < UniswapV4SingleStandardExchangeBufferConstantProductHookRepo.MINIMUM_LIQUIDITY) {
                revert UniswapV4SingleStandardExchangeDETFRepo.FirstBondBelowMinimumLiquidity();
            }
        }

        if (split_.userDetf > 0) _mintDetf(recipient_, split_.userDetf);

        tokenId_ = _openBondNft(shares_, lockDuration_, recipient_);
        UniswapV4SingleStandardExchangeDETFRepo._addUserBondedLp(shares_);

        if (!s.isReserveLive) {
            UniswapV4SingleStandardExchangeDETFRepo._setReserveLive();
            emit ReserveLive(tokenId_, shares_);
        }

        // D2 after createPosition, before pot mint, so ids 1–2 take this bond's pot at the new weights.
        _topUpFeeCreatorShares();
        if (split_.inventoryDetf > 0 && address(s.bondNftVault) != address(0)) {
            _mintDetf(address(s.bondNftVault), split_.inventoryDetf);
        }
        _tryCompoundProtocolRewards();
        _syncAllExpectedHoldReserves();
    }

    function _openBondNft(uint256 lpOut_, uint256 lockDuration_, address recipient_)
        private
        returns (uint256 tokenId_)
    {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.bondNftVault) == address(0) || lpOut_ == 0) return 0;
        tokenId_ = DETFBondLifecycleLib._createBondPosition(
            IDetfSelfNftInventoryPolicy(address(s.bondNftVault)),
            lpOut_,
            _effectiveLockDuration(lockDuration_),
            recipient_
        );
    }

    function sellPositionToDetfNft(uint256 tokenId_, address recipient_)
        public
        virtual
        nonReentrant
        returns (uint256 principalShares_)
    {
        _requireMature(tokenId_);
        _requireNotStandingRewardNft(tokenId_);
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (recipient_ == address(0)) recipient_ = msg.sender;

        // D10: transfer originalShares to id 0. Physical LP stays on the NFT vault (D13).
        if (address(s.rebasingClaimToken) == address(0)) {
            principalShares_ = DETFBondLifecycleLib._sellPositionToDetfNft(
                IDetfSelfNftInventoryPolicy(address(s.bondNftVault)), tokenId_, msg.sender, recipient_
            );
        } else {
            (principalShares_,) = DETFBondLifecycleLib._sellPositionToRebasingClaim(
                IDetfSelfNftInventoryPolicy(address(s.bondNftVault)),
                s.rebasingClaimToken,
                tokenId_,
                msg.sender,
                recipient_
            );
        }
        UniswapV4SingleStandardExchangeDETFRepo._subUserBondedLp(principalShares_);
        _topUpFeeCreatorShares();
        _tryCompoundProtocolRewards();
    }

    /// @inheritdoc IUniswapV4SingleStandardExchangeDETF
    function redeemClaim(
        uint256 claimAmount_,
        IERC20 tokenOut_,
        uint256 minOut_,
        address recipient_,
        uint256 deadline_
    ) public virtual nonReentrant returns (uint256 amountOut_) {
        amountOut_ = _redeemClaimForDetf(claimAmount_, tokenOut_, minOut_, recipient_, deadline_);
    }

    /// @dev D15: claim → DETF. Pending on id 0 first; leftover pending compounded; shortfall from LP.
    function _redeemClaimForDetf(
        uint256 claimAmount_,
        IERC20 tokenOut_,
        uint256 minOut_,
        address recipient_,
        uint256 deadline_
    ) internal returns (uint256 amountOut_) {
        _requireReserveLive();
        _requireActive(deadline_, claimAmount_);
        if (recipient_ == address(0)) recipient_ = msg.sender;

        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.rebasingClaimToken) == address(0)) revert UniswapV4SingleStandardExchangeDETFRepo.ClaimTokenNotConfigured();
        if (address(tokenOut_) != address(this)) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(s.rebasingClaimToken)), tokenOut_);
        }

        _realizeExpansionIfNeeded();

        uint256 lpOut_ = _burnClaimConvertToAssets(claimAmount_);
        uint256 owed_ = _previewZapOutToDetf(lpOut_);
        uint256 harvested_ = s.bondNftVault.reallocateDetfNftRewards(address(this));

        if (harvested_ >= owed_) {
            amountOut_ = owed_;
            uint256 leftover_ = harvested_ - owed_;
            if (leftover_ > 0) {
                uint256 lpBack_ = _depositSingleDetfCapped(leftover_, _bondLpHolder());
                if (lpBack_ > 0) {
                    s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpBack_);
                }
            }
            if (lpOut_ > 0) {
                s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpOut_);
            }
        } else {
            _pullNftLp(lpOut_);
            amountOut_ = _fillRedeemShortfall(lpOut_, harvested_, owed_, deadline_);
        }

        if (amountOut_ < minOut_) {
            revert IStandardExchangeErrors.MinAmountNotMet(minOut_, amountOut_);
        }
        if (amountOut_ > 0) {
            IERC20(address(this)).safeTransfer(recipient_, amountOut_);
        }
        _topUpFeeCreatorShares();
        _syncAllExpectedHoldReserves();
    }

    function _fillRedeemShortfall(uint256 lpOut_, uint256 harvested_, uint256 owed_, uint256 deadline_)
        private
        returns (uint256 amountOut_)
    {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        (uint256 detfFromLp_, uint256 pairOut_) = _withdrawProportional(lpOut_);
        uint256 shortfall_ = owed_ - harvested_;
        uint256 fromLp_ = detfFromLp_ < shortfall_ ? detfFromLp_ : shortfall_;
        amountOut_ = harvested_ + fromLp_;
        shortfall_ -= fromLp_;
        uint256 leftoverDetf_ = detfFromLp_ - fromLp_;
        uint256 nftLpLeft_ = IERC20(s.reserveHook).balanceOf(address(s.bondNftVault));
        if (shortfall_ > 0 && pairOut_ > 0 && nftLpLeft_ > 0) {
            s.pairToken.forceApprove(s.reserveHook, pairOut_);
            uint256 bought_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).ownerSwapExactIn(
                address(s.pairToken), address(this), pairOut_, 0, deadline_
            );
            pairOut_ = 0;
            uint256 take_ = bought_ < shortfall_ ? bought_ : shortfall_;
            amountOut_ += take_;
            leftoverDetf_ += bought_ - take_;
        }
        uint256 lpBack_;
        if (leftoverDetf_ > 0 && pairOut_ > 0) {
            lpBack_ = _depositProportional(leftoverDetf_, pairOut_, _bondLpHolder());
        } else if (leftoverDetf_ > 0) {
            lpBack_ = _depositSingleDetfCapped(leftoverDetf_, _bondLpHolder());
        } else if (pairOut_ > 0) {
            lpBack_ = _depositSinglePair(pairOut_, _bondLpHolder());
        }
        if (lpBack_ == 0 && (leftoverDetf_ > 0 || pairOut_ > 0)) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        if (lpBack_ > 0) {
            s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpBack_);
        }
    }

    function previewRedeemClaim(uint256 claimAmount_, IERC20 tokenOut_)
        external
        view
        returns (uint256 amountOut_)
    {
        if (claimAmount_ == 0) return 0;
        if (address(tokenOut_) != address(this)) return 0;
        uint256 lpOut_ = _previewClaimLpOut(claimAmount_);
        amountOut_ = _previewZapOutToDetf(lpOut_);
    }

    function buyClaim(
        uint256 detfAmount_,
        uint256 minClaimOut_,
        address recipient_,
        bool pretransferred_,
        uint256 deadline_
    ) public virtual nonReentrant returns (uint256 claimMinted_) {
        _requireNotDisabled();
        _requireReserveLive();
        _requireActive(deadline_, detfAmount_);
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.rebasingClaimToken) == address(0)) revert UniswapV4SingleStandardExchangeDETFRepo.ClaimTokenNotConfigured();
        if (recipient_ == address(0)) recipient_ = msg.sender;

        _pullToken(IERC20(address(this)), detfAmount_, pretransferred_);
        uint256 lpIn_ = _depositSingleDetf(detfAmount_, _bondLpHolder());
        if (lpIn_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();

        claimMinted_ = s.rebasingClaimToken.mintFromNFTSale(lpIn_, recipient_);
        s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpIn_);
        if (claimMinted_ < minClaimOut_) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(s.rebasingClaimToken)), IERC20(address(0)));
        }

        _topUpFeeCreatorShares();
        _realizeExpansionIfNeeded();
        _tryCompoundProtocolRewards();
        _syncAllExpectedHoldReserves();
    }

    function previewBuyClaim(uint256 detfAmount_) external view returns (uint256 claimMinted_) {
        if (detfAmount_ == 0) return 0;
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.rebasingClaimToken) == address(0)) return 0;
        uint256 lpIn_ = IUniswapV4SingleStandardExchangeBufferConstantProductHook(s.reserveHook).previewDepositSingle(address(this), detfAmount_);
        claimMinted_ = _previewClaimMinted(lpIn_, _protocolOriginalShares());
    }

    function joinDonatedCapital(IERC20 token_, uint256 amount_, uint256 deadline_)
        external
        nonReentrant
        returns (uint256 lpOut_)
    {
        _requireBondNft();
        _requireNotDisabled();
        _requireReserveLive();
        _requireActive(deadline_, amount_);
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(token_) == s.reserveHook) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(token_, s.pairToken);
        }
        if (address(token_) == address(this)) {
            uint256 pulled_ = _pullToken(token_, amount_, false);
            lpOut_ = _depositSingleDetf(pulled_, _bondLpHolder());
        } else {
            uint256 pairAmount_ = _settleToPair(token_, amount_, false, deadline_);
            lpOut_ = _depositSinglePair(pairAmount_, _bondLpHolder());
        }
        if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        _syncAllExpectedHoldReserves();
    }

    function previewJoinDonatedCapital(IERC20 token_, uint256 amount_)
        external
        view
        returns (uint256 lpOut_)
    {
        return _previewJoinDonatedCapital(token_, amount_);
    }

    function notifyReserveDonated() external {
        _requireBondNft();
        _topUpFeeCreatorShares();
    }

    /// @inheritdoc IUniswapV4SingleStandardExchangeDETF
    function donate(IERC20 token_, uint256 amount_, bool pretransferred_) external {
        _requireNotDisabled();
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        address nft_ = address(s.bondNftVault);
        if (nft_ == address(0)) revert UniswapV4SingleStandardExchangeDETFRepo.ReserveBondNftNotWired();
        IDetfNftReserveDonation(nft_).donate(
            msg.sender, token_, amount_, 0, pretransferred_, block.timestamp + 1
        );
    }

    function closeBondMature(
        uint256 tokenId_,
        uint256[] calldata minAmountsOut_,
        address recipient_,
        uint256 deadline_
    ) public virtual nonReentrant returns (uint256[] memory amountsOut_) {
        _requireMature(tokenId_);
        _requireNotStandingRewardNft(tokenId_);
        _requireActive(deadline_, 1);
        if (recipient_ == address(0)) recipient_ = msg.sender;

        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (minAmountsOut_.length != 2) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(0)), IERC20(address(0)));
        }
        if (minAmountsOut_[0] != 0) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(this)), IERC20(address(0)));
        }

        _realizeExpansionIfNeeded();

        uint256 lpOut_ = s.bondNftVault.convertToAssets(s.bondNftVault.originalSharesOf(tokenId_));
        if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        uint256 orig_ = s.bondNftVault.originalSharesOf(tokenId_);
        s.bondNftVault.retireMaturePosition(tokenId_, recipient_);
        UniswapV4SingleStandardExchangeDETFRepo._subUserBondedLp(orig_);

        _pullNftLp(lpOut_);
        (uint256 detfOut_, uint256 pairOut_) = _withdrawProportional(lpOut_);
        if (detfOut_ > 0) {
            uint256 lpRejoin_ = _depositSingleDetfUntilDust(detfOut_, _bondLpHolder());
            if (lpRejoin_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
            s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpRejoin_);
            _topUpFeeCreatorShares();
        }
        if (pairOut_ < minAmountsOut_[1]) {
            revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(s.pairToken, IERC20(address(0)));
        }
        if (pairOut_ > 0) {
            s.pairToken.safeTransfer(recipient_, pairOut_);
        }

        amountsOut_ = new uint256[](2);
        amountsOut_[1] = pairOut_;

        _tryCompoundProtocolRewards();
        _syncAllExpectedHoldReserves();
    }

    function previewCloseBondMature(uint256 tokenId_)
        external
        view
        returns (uint256[] memory amountsOut_)
    {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        amountsOut_ = new uint256[](2);
        uint256 assets_ = s.bondNftVault.originalSharesOf(tokenId_);
        if (assets_ == 0) return amountsOut_;
        uint256 lpOut_ = s.bondNftVault.convertToAssets(assets_);
        (, uint256 pairOut_) = _previewProportional(lpOut_);
        amountsOut_[1] = pairOut_;
    }

    function _burnClaimConvertToAssets(uint256 claimAmount_) private returns (uint256 lpOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        uint256 totalSharesBefore_ = s.rebasingClaimToken.totalShares();
        uint256 sharesBurned_ = s.rebasingClaimToken.burnShares(claimAmount_, msg.sender, false);
        if (sharesBurned_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        uint256 totalAssets_ = _protocolOriginalShares();
        uint256 totalShares_ = totalSharesBefore_ == 0 ? sharesBurned_ : totalSharesBefore_;
        lpOut_ = (sharesBurned_ * totalAssets_) / totalShares_;
        if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        s.bondNftVault.removeFromDETFNFT(s.bondNftVault.detfNFTId(), lpOut_);
    }

    function _previewClaimLpOut(uint256 claimAmount_) private view returns (uint256 lpOut_) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (address(s.rebasingClaimToken) == address(0)) return 0;
        uint256 shares_ = s.rebasingClaimToken.convertToShares(claimAmount_);
        uint256 totalShares_ = s.rebasingClaimToken.totalShares();
        uint256 totalAssets_ = _protocolOriginalShares();
        if (shares_ == 0 || totalShares_ == 0) return 0;
        lpOut_ = (shares_ * totalAssets_) / totalShares_;
    }

    function _previewClaimMinted(uint256 assets_, uint256 totalAssets_) private view returns (uint256) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        uint256 totalShares_ = s.rebasingClaimToken.totalShares();
        uint256 sharesOut_ = totalAssets_ == 0 ? assets_ : (assets_ * totalShares_) / totalAssets_;
        return s.rebasingClaimToken.convertToClaim(sharesOut_);
    }

    /// @inheritdoc IUniswapV4SingleStandardExchangeDETF
    function claimLiquidity(uint256 lpAmount_, address recipient_)
        external
        nonReentrant
        returns (uint256 pairOut_)
    {
        // _claimLiquidity ends with _syncAllExpectedHoldReserves (pair leave diamond).
        return _claimLiquidity(lpAmount_, recipient_);
    }

    /// @notice Realize expansion then harvest free DETF for the bond holder.
    /// @dev Holder must be `msg.sender`. Harvest is invoked on the NFT vault; the vault
    ///      authorizes the DETF owner for owner-initiated harvests only for protocol id —
    ///      so user harvest is expected via the NFT surface. This path realizes debt first,
    ///      then attempts NFT claim (works when NFT allows DETF-or-holder; otherwise use NFT).
    function claimRewards(uint256 tokenId_, address recipient_)
        public
        virtual
        nonReentrant
        returns (uint256 rewards_)
    {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        if (recipient_ == address(0)) recipient_ = msg.sender;
        _realizeExpansionIfNeeded();
        // L-REW-1: owner-only; non-owner reverts (no soft-success).
        address holder_ = s.bondNftVault.ownerOf(tokenId_);
        if (msg.sender != holder_) {
            revert UniswapV4SingleStandardExchangeDETFRepo.NotAuthorized(msg.sender);
        }
        // L-REW-2/3: no try/catch soft-fail; return 0 only when allowed and zero rewards.
        rewards_ = s.bondNftVault.claimRewards(tokenId_, recipient_);
        _tryCompoundProtocolRewards();
    }

